/**
 * formatInfo.js —— 格式说明知识库
 *
 * 为渲染层提供每种文件格式的中英文说明：这是什么格式、关键性质，以及它的字节是怎么排布的。
 * 数据按规范格式名（全小写，扩展名别名已由宿主规范化）索引，每个条目给出 zh 与 en 两套
 * summary / traits / layout 文本，供格式详情面板直接展示，不含任何逻辑或副作用。
 */

const INFO = {
  '3gp': {
    zh: { summary: '3GPP 定义的移动多媒体容器，基于 ISO 基础媒体文件格式，用于早期手机录像与视频通话。', traits: ['容器', '有损', '压缩'], layout: '盒式结构：前 4 字节是盒长度，随后 ftyp 盒给出品牌（3gp4、3gp5 等），再有 moov 盒（轨道与时长）与 mdat 盒（媒体数据）；音视频样本按时间索引，全部大端字节序。' },
    en: { summary: 'Mobile multimedia container defined by 3GPP on the ISO base media file format, used for early phone recording and video calls; video is usually H.263 or H.264 and audio is AMR or AAC, both lossy.', traits: ['Container', 'Lossy', 'Compressed'], layout: 'Box structure: the first four bytes hold a box length, then an ftyp box names the brand (3gp4, 3gp5 and so on), followed by moov (tracks and durations) and mdat (media payload); samples are indexed by time and all fields are big-endian.' },
  },
  '7z': {
    zh: { summary: '7-Zip 的归档格式，默认用 LZMA 或 LZMA2 压缩，支持固实压缩、AES-256 加密与超长路径。', traits: ['压缩', '无损', '容器', '加密'], layout: '文件以 6 字节签名 37 7A BC AF 27 1C 开头，随后是版本号与起始头 CRC；起始头指明压缩头的位置，头内保存编码器链、文件夹（数据块）与文件条目，附加数据可带 AES 加密与 CRC32 校验。' },
    en: { summary: 'Archive format of 7-Zip, normally compressed with LZMA or LZMA2; it supports solid blocks, AES-256 encryption and very long paths, and usually beats ZIP on compression ratio.', traits: ['Compressed', 'Lossless', 'Container', 'Encrypted'], layout: 'The file starts with the six-byte signature 37 7A BC AF 27 1C, then a version byte and the start header CRC; that header points to a compressed header holding the coder chain, folders (data blocks) and file entries, with optional AES encryption and CRC32 checksums.' },
  },
  'aac': {
    zh: { summary: '高级音频编码，MPEG-2 与 MPEG-4 的有损音频方案，用改良离散余弦变换配合心理声学模型压缩。', traits: ['有损', '压缩', '流式'], layout: '常见两种排布：ADTS 裸流每帧以 12 位同步字 FF F 开头，帧头含配置、采样率索引与帧长，可从任意帧开始解码；封装进 MP4 时由 mp4a 样本条目描述，帧数据放在 mdat 盒中。另有 ADIF 整体头变体。' },
    en: { summary: 'Advanced Audio Coding, the lossy audio scheme of MPEG-2 and MPEG-4; it pairs a modified discrete cosine transform with psychoacoustic modelling and beats MP3 at the same bitrate, stored as ADTS streams or inside MP4.', traits: ['Lossy', 'Compressed', 'Streamable'], layout: 'Two common layouts: ADTS streams start each frame with the 12-bit sync word FF F, and the frame header carries the profile, sample-rate index and frame length so decoding can begin at any frame; inside MP4 an mp4a sample entry describes frames kept in the mdat box. An ADIF variant keeps one global header.' },
  },
  'adoc': {
    zh: { summary: 'AsciiDoc 标记语言的纯文本源文件，用行首符号表达标题、列表与表格，能转成 HTML、DocBook 或 PDF。', traits: ['纯文本', '可编辑', '未压缩'], layout: '纯文本，无二进制签名。标题以行首一到六个等号标记，代码块与引用块用四个以上连字符或点号围栏，属性以冒号开头单独成行；换行通常为 LF，工具按 UTF-8 读取，扩展名 adoc 与 asciidoc 等价。' },
    en: { summary: 'Plain-text source of the AsciiDoc markup language; leading characters express headings, lists and tables, and it converts to HTML, DocBook or PDF, which suits technical documentation and books.', traits: ['Plain text', 'Editable', 'Uncompressed'], layout: 'Plain text with no binary signature. Headings use one to six leading equals signs, code and quote blocks are fenced with four or more hyphens or dots, and attributes are declared on their own lines starting with a colon; lines end in LF and tools assume UTF-8. The adoc and asciidoc extensions are equivalent.' },
  },
  'ai': {
    zh: { summary: 'Adobe Illustrator 矢量绘图文档；早期为 PostScript 文件，此后改为 PDF 兼容数据。', traits: ['矢量', '可编辑', '元数据'], layout: '没有固定签名：老文件以 PostScript 头 %!PS-Adobe- 开头，现代文件以 %PDF- 开头，Illustrator 私有信息放在注释或自定义 PDF 对象中，末尾通常有 %%EOF；图形由路径、贝塞尔曲线与着色指令描述，可内嵌位图。' },
    en: { summary: 'Vector graphics document from Adobe Illustrator; older releases are PostScript files with private comments, while version 9 and later store PDF-compatible data, so other tools can often read them as PDF.', traits: ['Vector', 'Editable', 'Metadata'], layout: 'No fixed signature: old files begin with the PostScript header %!PS-Adobe-, modern ones with %PDF-, and Illustrator private data sits in comments or custom PDF objects, usually ending with %%EOF. Artwork is described by paths, Bezier curves and painting operators, optionally with embedded raster images.' },
  },
  'aiff': {
    zh: { summary: 'Apple 的音频交换文件格式，以未压缩线性 PCM 存储样本，常见 16 位 44.1 kHz；采用大端字节序。', traits: ['未压缩', '无损', '容器'], layout: '以 4 字节 FORM 开头，随后 4 字节大端长度与类型 AIFF（AIFC 为压缩变体）；之后是若干 chunk：COMM 保存声道数、采样帧数与 80 位扩展浮点采样率，SSND 保存 PCM 数据，另有 NAME、ANNO 等可选文本块。' },
    en: { summary: 'Apple audio interchange file format storing uncompressed linear PCM samples, typically 16-bit 44.1 kHz in big-endian order; it coexists with WAV in professional audio work.', traits: ['Uncompressed', 'Lossless', 'Container'], layout: 'Begins with the four bytes FORM, a 4-byte big-endian length and the type AIFF (AIFC for compressed variants); chunks follow: COMM holds channel count, sample frames and the sample rate as an 80-bit extended float, SSND holds the PCM data, and optional NAME or ANNO chunks hold text.' },
  },
  'amr': {
    zh: { summary: '自适应多速率语音编码，为蜂窝网络设计的窄带单声道语音格式，码率可在 4.75 至 12.2 kbps 间切换。', traits: ['有损', '压缩', '流式'], layout: '文件以 ASCII 头 #!AMR 加换行开头（宽带变体为 #!AMR-WB），其后是连续帧，每帧首字节含帧类型与质量位，帧长由帧类型决定，因此可以逐帧丢弃或插入以适配网络。' },
    en: { summary: 'Adaptive Multi-Rate speech codec, a narrowband mono voice format designed for cellular networks; the bitrate switches between 4.75 and 12.2 kbps and quality is clearly below that of music codecs.', traits: ['Lossy', 'Compressed', 'Streamable'], layout: 'The file starts with the ASCII header #!AMR plus a line break (wideband variants use #!AMR-WB); after that come consecutive frames whose first byte encodes the frame type and a quality bit, with frame length fixed by the type, so frames can be dropped or inserted individually.' },
  },
  'asciidoc': {
    zh: { summary: 'AsciiDoc 文档的规范扩展名之一，内容与 adoc 相同：纯文本标记加属性与宏，由处理器渲染为 HTML。', traits: ['纯文本', '可编辑', '未压缩'], layout: '纯文本，无二进制签名。结构由行首标记决定：等号表示标题层级，星号或连字符表示列表，竖线构成表格，方括号给出块属性，另有 include、image 等宏；文件通常为 UTF-8 与 LF 换行，不含版本号或校验字段。' },
    en: { summary: 'One of the canonical extensions for AsciiDoc documents, identical in content to adoc: plain-text markup with attributes and macros that a processor renders to HTML, DocBook or PDF.', traits: ['Plain text', 'Editable', 'Uncompressed'], layout: 'Plain text with no binary signature. Structure comes from leading characters: equals signs for heading levels, asterisks or hyphens for lists, pipes for tables, bracketed block attributes, plus macros such as include and image. Files are normally UTF-8 with LF endings and carry no version or checksum fields.' },
  },
  'asf': {
    zh: { summary: '微软高级系统格式，是 WMV 与 WMA 的底层容器；由以全局唯一标识符标记的对象组成，支持流式传输。', traits: ['容器', '有损', '流式', '元数据'], layout: '以 16 字节头对象 GUID 30 26 B2 75 8E 66 CF 11 A6 D9 00 AA 00 62 CE 6C 开头，随后是 8 字节对象大小与对象数量；内部对象同样以 GUID 加长度开头，包括头对象（流属性与编解码信息）、数据对象与可选索引对象，字段小端。' },
    en: { summary: 'Microsoft Advanced Systems Format, the container beneath WMV and WMA; it is built from objects tagged with globally unique identifiers and supports streaming, indexing and digital rights management.', traits: ['Container', 'Lossy', 'Streamable', 'Metadata'], layout: 'Starts with the 16-byte header object GUID 30 26 B2 75 8E 66 CF 11 A6 D9 00 AA 00 62 CE 6C, then an 8-byte object size and object count; inner objects also begin with a GUID and length, covering the header object (stream properties and codec info), the data object and optional index objects, all little-endian.' },
  },
  'avi': {
    zh: { summary: '微软的音频视频交错容器，基于 RIFF；把视频帧与音频块交错存放便于同步播放，兼容性极好。', traits: ['容器', '压缩', '元数据'], layout: '以 4 字节 RIFF 加 4 字节小端长度与类型标识 AVI 开头，随后是嵌套块：hdrl 描述流与编码器，movi 按时间交错存放音频与视频帧，文件尾或 movi 之后的 idx1 块保存每帧的偏移与大小索引。' },
    en: { summary: 'Microsoft Audio Video Interleave container built on RIFF; video frames and audio chunks are interleaved for easy synchronised playback, with excellent compatibility but weak indexing and no support for modern codec features.', traits: ['Container', 'Compressed', 'Metadata'], layout: 'Starts with the four bytes RIFF, a 4-byte little-endian length and the type tag AVI, then nested chunks: hdrl describes streams and codecs, movi holds interleaved audio and video frames, and an idx1 chunk after movi or at the end indexes each frame offset and size.' },
  },
  'avif': {
    zh: { summary: '基于 AV1 的图像格式，用 HEIF 系的 ISO 基础媒体文件格式封装；压缩率优于 JPEG 与 WebP。', traits: ['有损', '无损', '支持透明', '压缩'], layout: '盒式结构，以 ftyp 盒开头且品牌为 avif（图像序列为 avis），meta 盒给出图像空间与 iprp 属性，mdat 盒内是 AV1 帧数据，一小段 AV1 序列头通常放在 av1C 配置盒中；全部字段大端。' },
    en: { summary: 'Image format based on AV1, wrapped in the HEIF flavour of the ISO base media file format; it compresses better than JPEG and WebP and supports 10-bit and 12-bit depth, HDR, alpha and image sequences.', traits: ['Lossy', 'Lossless', 'Alpha', 'Compressed'], layout: 'Box structure starting with an ftyp box whose brand is avif (avis for sequences); a meta box carries the image space and iprp properties, AV1 frame data lives in mdat, and the small AV1 sequence header is usually kept in an av1C configuration box. Every field is big-endian.' },
  },
  'bib': {
    zh: { summary: 'BibTeX 参考文献数据库，纯文本记录条目，常与 LaTeX 配合由 bibtex 或 biber 生成文献表。', traits: ['纯文本', '可编辑', '无损'], layout: '纯文本，无二进制签名。每条以 @ 加条目类型（article、book 等）开始，后接花括号或圆括号，第一个字段是引用键，其余字段写成 名称 = 值 并用逗号分隔；@string 定义缩写，@comment 与 @preamble 为特殊条目。' },
    en: { summary: 'BibTeX bibliography database of plain-text records, normally paired with LaTeX so bibtex or biber can build the reference list; it stores bibliographic fields only and never describes layout.', traits: ['Plain text', 'Editable', 'Lossless'], layout: 'Plain text with no binary signature. Each record starts with @ plus a type such as article or book, followed by braces or parentheses, with the first field being the citation key and the rest written as name = value pairs separated by commas; @string defines abbreviations while @comment and @preamble are special entries.' },
  },
  'bmp': {
    zh: { summary: 'Windows 位图，结构极简的光栅格式，支持 1、4、8、24、32 位与调色板；几乎不压缩，文件体积大。', traits: ['位图', '未压缩', '无损', '元数据'], layout: '以两字节 42 4D 开头，即字符 BM，随后是 14 字节文件头（文件大小、像素数据偏移），再接 40 字节起的 DIB 头（宽高、位深、压缩方式、行对齐）；像素按行自底向上存放，每行补齐到 4 字节边界，8 位及以下用调色板。' },
    en: { summary: 'Windows bitmap, a minimal raster format supporting 1, 4, 8, 24 and 32-bit depths plus palettes; it barely compresses so files are large, which suits icons, textures and quick read-write paths.', traits: ['Raster', 'Uncompressed', 'Lossless', 'Metadata'], layout: 'Starts with the two bytes 42 4D, the characters BM, then a 14-byte file header (file size, pixel data offset) and a DIB header of 40 bytes or more (width, height, bit depth, compression, row alignment); pixels are stored bottom-up with rows padded to 4-byte boundaries, and depths of 8 bits and below use a palette.' },
  },
  'bz2': {
    zh: { summary: 'bzip2 的单文件压缩流，先用 Burrows-Wheeler 变换重排数据再做霍夫曼编码。', traits: ['压缩', '无损', '流式'], layout: '以 3 字节 BZh 加一位级别数字（1 到 9，决定 100 到 900 KB 的块大小）开头，之后是若干数据块，每块带 48 位魔数 31 41 59 26 53 59 与自身 CRC，块内数据经 BWT 与 MTF 后霍夫曼编码，流尾给出整体 CRC 与填充。' },
    en: { summary: 'Single-stream compressor from bzip2 that applies a Burrows-Wheeler transform before Huffman coding; it usually beats gzip on ratio but runs slower and compresses one file only, so tar handles archiving.', traits: ['Compressed', 'Lossless', 'Streamable'], layout: 'Begins with the three bytes BZh plus a level digit from 1 to 9 that sets the 100 to 900 KB block size; blocks follow, each marked by the 48-bit magic 31 41 59 26 53 59 with its own CRC, and block data is Huffman-coded after the BWT and move-to-front stages. A trailing CRC and padding close the stream.' },
  },
  'cab': {
    zh: { summary: '微软 Cabinet 压缩归档，Windows 安装程序与系统更新长期使用；支持多文件、分卷与数字签名。', traits: ['压缩', '无损', '容器'], layout: '以 4 字节 MSCF 开头，随后是 36 字节头（总大小、文件数、文件夹数与标志），再是可选保留字段、前一个与后一个 Cabinet 名称、文件夹条目与文件条目表；数据按文件夹分块存放，每块前有 CFDATA 结构与校验和。' },
    en: { summary: 'Microsoft Cabinet archive, long used by Windows installers and system updates; it holds multiple files, supports spanning and digital signatures, and compresses with MSZIP, Quantum or LZX.', traits: ['Compressed', 'Lossless', 'Container'], layout: 'Starts with the four bytes MSCF, then a 36-byte header (total size, file and folder counts, flags), optional reserved fields, previous and next cabinet names, folder and file entry tables; payload data is grouped per folder into blocks, each preceded by a CFDATA structure and checksum.' },
  },
  'cdr': {
    zh: { summary: 'CorelDRAW 的矢量绘图文档，格式专有且随版本变化；内部基于 RIFF 存储，含矢量对象、位图预览与页面设置。', traits: ['矢量', '可编辑', '元数据'], layout: '文件以 4 字节 RIFF 加小端长度与类型标识开头，类型随版本不同（如 CDR9、CDRX），随后是若干块状结构，保存绘图设置、字体与颜色表以及对象和页面描述；结构未公开且各版本差异较大，末尾常含缩略图预览数据。' },
    en: { summary: 'CorelDRAW vector drawing document, proprietary and version-dependent; it is RIFF-based internally and can hold vector objects, a bitmap preview and page setup at once, with limited cross-version compatibility.', traits: ['Vector', 'Editable', 'Metadata'], layout: 'The file opens with the four bytes RIFF, a little-endian length and a type tag that varies by version (CDR9, CDRX and others), followed by chunked structures holding drawing settings, font and colour tables, and object and page descriptions; the layout is undocumented and differs between versions, usually ending with embedded thumbnail data.' },
  },
  'csv': {
    zh: { summary: '逗号分隔值的纯文本表格，遵循 RFC 4180 用逗号分列、换行分行；不携带类型与样式信息，几乎所有表格软件都能读写。', traits: ['纯文本', '可编辑', '未压缩'], layout: '纯文本，无二进制签名。每行一条记录，字段以逗号分隔，字段内含逗号、引号或换行时用双引号包裹并把内部引号写成两个；行分隔通常是 CRLF 或 LF，编码常为 UTF-8（Excel 习惯加 BOM），首行是否为表头靠约定。' },
    en: { summary: 'Plain-text tabular data with comma-separated values following RFC 4180, where commas split columns and line breaks split rows; no types or styling are carried and nearly every spreadsheet tool can read and write it.', traits: ['Plain text', 'Editable', 'Uncompressed'], layout: 'Plain text with no binary signature. Each line is a record of comma-separated fields, and a field containing a comma, quote or newline is wrapped in double quotes with inner quotes doubled; line endings are usually CRLF or LF, encoding is often UTF-8 (Excel tends to add a BOM), and whether the first row is a header is purely conventional.' },
  },
  'cur': {
    zh: { summary: 'Windows 鼠标光标文件，与 ICO 结构相同，但在目录项中额外记录热点坐标；可存放多个尺寸与色深。', traits: ['位图', '支持透明', '元数据'], layout: '以 6 字节 ICONDIR 开头（保留字段 00 00、类型 02 表示光标、图像数），随后每个图像一个 16 字节目录项，给出宽高、色数、位面与字节数，其中末两字节是热点 X 与 Y；图像数据为 DIB 或内嵌 PNG。' },
    en: { summary: 'Windows mouse cursor file, structurally the same as ICO but with hotspot coordinates recorded in each directory entry; it can hold several sizes and colour depths and supports 32-bit alpha blending.', traits: ['Raster', 'Alpha', 'Metadata'], layout: 'Opens with a 6-byte ICONDIR (reserved 00 00, type 02 for cursors, image count), then a 16-byte directory entry per image giving width, height, colour count, planes and byte size, whose last two bytes are the hotspot X and Y; image data is either a DIB or an embedded PNG.' },
  },
  'dds': {
    zh: { summary: 'DDS 即 DirectDraw Surface，游戏常用纹理容器；可用 DXT、BC 块压缩并支持 mipmap。', traits: ['位图', '压缩', '支持透明', '元数据'], layout: '以 4 字节魔数 44 44 53 20 开头，即字符 DDS 加空格，随后是 124 字节头：大小、标志、高宽、mipmap 层数、像素格式结构（FourCC 如 DXT1、DXT5、BC7 或 RGB 掩码），可选 20 字节 DX10 扩展头给出 DXGI 格式。' },
    en: { summary: 'DirectDraw Surface, a texture container widely used in games and real-time rendering; it stores raw pixels or DXT/BC block-compressed data and supports mipmap chains, cube maps and alpha.', traits: ['Raster', 'Compressed', 'Alpha', 'Metadata'], layout: 'Opens with the four-byte magic 44 44 53 20, the characters DDS plus a space, then a 124-byte header: size, flags, height and width, mipmap count and a pixel format structure carrying a FourCC such as DXT1, DXT5 or BC7, or plain RGB masks; an optional 20-byte DX10 header names a DXGI format, and pixel data follows mip level by mip level.' },
  },
  'djot': {
    zh: { summary: 'Djot 标记语言的纯文本源文件，语法比 Markdown 更严格、歧义更少，用围栏与属性块表达结构。', traits: ['纯文本', '可编辑', '无损'], layout: '纯文本，无二进制签名。内联标记用成对的星号、下划线或插入符表示强调与上下标，块级元素用三个以上冒号围栏或行首符号开启，属性写成花括号内的键值对，段落之间以空行分隔；通常保存为 UTF-8 与 LF 换行。' },
    en: { summary: 'Plain-text source of the Djot markup language, whose syntax is stricter and less ambiguous than Markdown; fenced blocks and attribute lists carry structure, and a converter renders it to HTML and similar targets.', traits: ['Plain text', 'Editable', 'Lossless'], layout: 'Plain text with no binary signature. Inline markup uses paired asterisks, underscores or carets for emphasis and sub/superscripts, block elements open with fences of three or more colons or with leading characters, attributes are key-value pairs in braces, and paragraphs are separated by blank lines; files are normally UTF-8 with LF endings.' },
  },
  'doc': {
    zh: { summary: 'Word 97 至 2003 的二进制文档，用 OLE2 复合文件保存文本、格式与嵌入对象；结构复杂且只部分公开。', traits: ['容器', '可编辑', '元数据'], layout: '以 OLE2 复合文件的 8 字节签名 D0 CF 11 E0 A1 B1 1A E1 开头，内部是一个小型文件系统，含 FAT、目录项与若干命名流；正文在 WordDocument 流，格式化与字符位置信息在 1Table 或 0Table 流，图片等对象以子存储存在。' },
    en: { summary: 'Binary Word document from Word 97 through 2003, storing text, formatting and embedded objects in an OLE2 compound file; the layout is complex and only partly documented, and current Word releases still read it.', traits: ['Container', 'Editable', 'Metadata'], layout: 'Begins with the 8-byte OLE2 compound file signature D0 CF 11 E0 A1 B1 1A E1 and contains a small file system with a FAT, directory entries and named streams; the text lives in the WordDocument stream, formatting and character positions in the 1Table or 0Table stream, and pictures are kept as sub-storages.' },
  },
  'docbook': {
    zh: { summary: '基于 XML 的结构化文档标记，用 DTD 或 Schema 定义章节、段落与交叉引用等语义元素。', traits: ['纯文本', '可编辑', '多页'], layout: '纯文本，无二进制签名。文件以 XML 声明开头，根元素通常是 book、article 或 chapter，可带 DOCTYPE 指向 DocBook DTD；正文全为成对的元素标记与实体引用，编码一般为 UTF-8，换行 LF，不含二进制字段。' },
    en: { summary: 'Structured XML document markup whose DTD or schema defines semantic elements such as chapters, paragraphs and cross references; stylesheets then convert it to HTML, PDF or man pages.', traits: ['Plain text', 'Editable', 'Multi-page'], layout: 'Plain text with no binary signature. The file opens with an XML declaration and the root element is normally book, article or chapter, optionally followed by a DOCTYPE pointing at the DocBook DTD; the body is paired element tags and entity references, normally UTF-8 with LF endings and no binary fields.' },
  },
  'docm': {
    zh: { summary: 'Word 2007 及以后启用宏的文档，与 docx 同为 OOXML 包，额外带 VBA 工程，打开时可能执行宏。', traits: ['压缩', '容器', '可编辑', '加密'], layout: '本质是 ZIP 包，以本地文件头 50 4B 03 04 开头，内含 [Content_Types].xml 与 word/document.xml 等部件；宏代码放在 word/vbaProject.bin 二进制部件中，关系由 .rels 文件描述。' },
    en: { summary: 'Macro-enabled Word document from Word 2007 onward; it is an OOXML package like docx but also carries a VBA project, so opening it may run macros and security tools flag it accordingly.', traits: ['Compressed', 'Container', 'Editable', 'Encrypted'], layout: 'It is a ZIP package whose local file header starts with 50 4B 03 04, holding parts such as [Content_Types].xml and word/document.xml; macro code sits in the binary part word/vbaProject.bin, relationships are described in .rels files, and the whole package can be encrypted with OOXML Agile Encryption.' },
  },
  'docx': {
    zh: { summary: 'Office Open XML 文字文档，用 ZIP 打包若干 XML 部件描述文本、样式、图片与批注；结构开放。', traits: ['压缩', '容器', '可编辑', '元数据'], layout: 'ZIP 容器，以 50 4B 03 04 开头；[Content_Types].xml 声明部件类型，_rels/.rels 指向主部件 word/document.xml，样式、编号、页眉页脚各为独立 XML 部件，图片放在 word/media 目录；部件路径即关系标识。' },
    en: { summary: 'Office Open XML word-processing document that packs XML parts for text, styles, images and comments into a ZIP; the open structure is supported by many non-Microsoft tools and the package can be encrypted as a whole.', traits: ['Compressed', 'Container', 'Editable', 'Metadata'], layout: 'A ZIP container starting with 50 4B 03 04: [Content_Types].xml declares part types, _rels/.rels points at the main part word/document.xml, and styles, numbering and headers or footers each live in their own XML parts with images under word/media; part paths act as relationship identifiers, and ECMA-376 encryption is optional.' },
  },
  'dpx': {
    zh: { summary: '数字图像交换格式，由 SMPTE 268M 标准化，用于电影扫描与后期流程。', traits: ['位图', '未压缩', '元数据'], layout: '以 4 字节魔数开头：大端为 53 44 50 58 即 SDPX，小端为 58 50 44 53 即 XPDS；随后是图像数据偏移、版本与文件大小，接着是 1664 字节通用头、图像头与可选的方向头，最后是像素数据，常为 10 位打包 RGB 或 YCbCr。' },
    en: { summary: 'Digital Picture Exchange format, standardised as SMPTE 268M for film scanning and post-production; it stores 10-bit or 16-bit pixels in log or linear form and is uncompressed though bulky.', traits: ['Raster', 'Uncompressed', 'Metadata'], layout: 'Begins with a 4-byte magic: 53 44 50 58 (SDPX) for big-endian or 58 50 44 53 (XPDS) for little-endian, followed by the image data offset, version and file size, then a 1664-byte generic header, an image header and an optional orientation header, with pixel data last, often 10-bit packed RGB or YCbCr.' },
  },
  'dxf': {
    zh: { summary: 'AutoCAD 的图形交换格式，主要为纯文本，用组码与值成对描述图层、实体与块；二维图纸交换的标准。', traits: ['纯文本', '可编辑', '矢量', '元数据'], layout: '纯文本，无二进制签名。内容由组码与值交替成对组成，每项占两行；文件按 SECTION 与 ENDSEC 分成 HEADER、TABLES、BLOCKS、ENTITIES 等段，整体以 EOF 结束。另有二进制变体，开头带 AutoCAD Binary DXF 字样。' },
    en: { summary: 'AutoCAD Drawing Exchange Format, mostly plain text, describing layers, entities and blocks as group code and value pairs; it is the standard for exchanging 2D drawings and can also hold 3D wireframes and surfaces.', traits: ['Plain text', 'Editable', 'Vector', 'Metadata'], layout: 'Plain text with no binary signature. Content is a sequence of group code and value pairs, one per line each; the file is split into HEADER, TABLES, BLOCKS and ENTITIES sections delimited by SECTION and ENDSEC, and it ends with EOF. A binary variant exists and begins with the text AutoCAD Binary DXF.' },
  },
  'emf': {
    zh: { summary: '增强型图元文件，Windows 的矢量图形记录格式，绘图动作以记录序列保存，因此可缩放；既能含矢量也能内嵌位图。', traits: ['矢量', '位图', '元数据'], layout: '以头记录开头：记录类型 01 00 00 00，偏移 40 字节处是签名 20 45 4D 46 即 EMF 加空格，头给出边界矩形与设备单位；其后每条记录都是 4 字节类型加 4 字节长度再加数据，最后以类型 14 的 EOF 记录结束。' },
    en: { summary: 'Enhanced Metafile, a Windows vector recording format that stores drawing actions as a record sequence and therefore scales cleanly; it can hold vector content and embedded bitmaps, and is common in Office files and printing.', traits: ['Vector', 'Raster', 'Metadata'], layout: 'Starts with a header record whose type is 01 00 00 00 and whose signature at offset 40 is 20 45 4D 46, the characters EMF plus a space, with bounds and device units in the header; every later record is a 4-byte type, a 4-byte length and its data, and the file ends with an EOF record of type 14.' },
  },
  'epub': {
    zh: { summary: '电子书标准格式，用 ZIP 容器装 XHTML 内容与 CSS、图片、字体，支持可重排排版、目录导航与元数据。', traits: ['容器', '压缩', '多页', '元数据', '加密'], layout: 'ZIP 包，但首个条目 mimetype 必须以存储方式未压缩保存，内容为 application/epub+zip；随后 META-INF/container.xml 指向 OPF 包文档，OPF 列出清单、书脊与元数据，正文为 XHTML 文件。' },
    en: { summary: 'Ebook standard format that packs XHTML content with CSS, images and fonts into a ZIP container, supporting reflowable layout, navigation and metadata; DRM encryption is possible.', traits: ['Container', 'Compressed', 'Multi-page', 'Metadata', 'Encrypted'], layout: 'A ZIP package whose first entry, mimetype, must be stored uncompressed and contains application/epub+zip; META-INF/container.xml then points to the OPF package document, which lists the manifest, spine and metadata, the content is XHTML, and DRM is described in META-INF/encryption.xml.' },
  },
  'exif': {
    zh: { summary: '通常指携带 Exif 元数据的 JPEG 或 TIFF 图像：记录相机型号、拍摄参数、时间与方向等信息。', traits: ['位图', '元数据', '有损'], layout: '若为 JPEG，则以 SOI 的 FF D8 开头，在 APP1 段（标记 FF E1）中写入 Exif 标识 45 78 69 66 00 00 与 00 00，随后是 TIFF 头（II 2A 00 或 MM 00 2A）与 IFD 链。' },
    en: { summary: 'Usually a JPEG or TIFF image carrying Exif metadata: camera model, exposure settings, timestamps and orientation, while the pixel data stays in the base format.', traits: ['Raster', 'Metadata', 'Lossy'], layout: 'For JPEG the file opens with the SOI marker FF D8 and an APP1 segment (marker FF E1) holding the Exif identifier 45 78 69 66 00 00 plus 00 00, then a TIFF header (II 2A 00 or MM 00 2A) and a chain of IFDs, each an entry count, an array of tagged entries and an offset to the next IFD.' },
  },
  'exr': {
    zh: { summary: 'OpenEXR 高动态范围图像格式，由 ILM 开发；以 half 或 float 保存线性场景光值，支持多通道。', traits: ['位图', '支持透明', '无损', '有损', '元数据'], layout: '以 4 字节魔数 76 2F 31 01 开头，接着 4 字节版本与标志；头部是若干属性，每项为以 0 结尾的属性名加类型名、4 字节长度与值，属性列表以单个 0 字节结束，随后是扫描线偏移表与分块数据，压缩可选 RLE、ZIP、PIZ、B44 或 DWAA。' },
    en: { summary: 'OpenEXR high dynamic range image format from ILM; it stores linear scene values as half or float, supports multiple channels and parts with several lossless or lossy codecs, and is standard in film compositing.', traits: ['Raster', 'Alpha', 'Lossless', 'Lossy', 'Metadata'], layout: 'Starts with the 4-byte magic 76 2F 31 01 and a 4-byte version and flags field; the header is a list of attributes, each a null-terminated name and type name plus a 4-byte length and value, terminated by a single zero byte, followed by a scanline offset table and chunked data with optional RLE, ZIP, PIZ, B44 or DWAA compression.' },
  },
  'fits': {
    zh: { summary: '天文学通用数据格式，用 ASCII 关键字头描述图像或表格数据，可包含多个数据单元；天文望远镜与观测档案的事实标准。', traits: ['元数据', '位图', '未压缩'], layout: '头部为定长 2880 字节的记录，由 36 张 80 字符的卡片拼成，首卡固定为 SIMPLE  = T，末尾有 END 卡片，其余用空格补齐；数据段随头部记录号顺序存放，数值为大端，一次文件可含多个头部加数据单元。' },
    en: { summary: 'Flexible Image Transport System, the standard astronomy data format: ASCII keyword headers describe image or table data and one file may contain several data units, as used by telescopes and observatories.', traits: ['Metadata', 'Raster', 'Uncompressed'], layout: 'The header is made of fixed 2880-byte records of thirty-six 80-character cards, the first card always reading SIMPLE  = T and the last END, with the rest padded by spaces; data units follow their header record and store numbers big-endian, and a file can hold several header plus data units in sequence.' },
  },
  'flac': {
    zh: { summary: '自由无损音频压缩格式，压缩率约为原 PCM 的一半；用线性预测与 Rice 编码，支持流式解码、多声道与高采样率。', traits: ['无损', '压缩', '流式', '元数据'], layout: '以 4 字节魔数 66 4C 61 43 开头，即字符 fLaC；随后是元数据块序列，首块必须是 STREAMINFO（采样率、声道、总样本数与 MD5），之后可有 VORBIS_COMMENT、PICTURE 等块，最后一块的标志位为 1；音频帧紧随其后。' },
    en: { summary: 'Free lossless audio codec, typically halving original PCM size; it uses linear prediction plus Rice coding, supports streamed decoding, multichannel and high sample rates, and decodes back to bit-identical audio.', traits: ['Lossless', 'Compressed', 'Streamable', 'Metadata'], layout: 'Starts with the four-byte magic 66 4C 61 43, the characters fLaC; metadata blocks follow, the first being STREAMINFO with sample rate, channels, total samples and an MD5, then optional blocks such as VORBIS_COMMENT or PICTURE, the last one flagged as final; audio frames come next, each with a header coding block size and sample rate.' },
  },
  'flv': {
    zh: { summary: 'Flash 视频容器，曾广泛用于网页嵌入播放；把音频、视频与脚本数据存为标签序列，现已基本被淘汰。', traits: ['容器', '有损', '流式', '元数据'], layout: '以 3 字节 46 4C 56 开头，即字符 FLV，随后是 1 字节版本、1 字节标志与 4 字节头长度；之后是标签序列，每个标签前有 4 字节上一标签长度，标签体为 1 字节类型（音频、视频、脚本）、3 字节数据长度、3 字节时间戳与流标识。' },
    en: { summary: 'Flash Video container once widespread for embedded web playback; it stores audio, video and script data as a tag sequence, with H.263, VP6 or H.264 video, and is now largely obsolete.', traits: ['Container', 'Lossy', 'Streamable', 'Metadata'], layout: 'Starts with the three bytes 46 4C 56, the characters FLV, then a version byte, a flags byte and a 4-byte header size; tags follow, each preceded by the previous tag size, and the tag body holds a 1-byte type (audio, video, script), a 3-byte data size, a 3-byte timestamp and a stream identifier.' },
  },
  'fodp': {
    zh: { summary: 'OpenDocument 演示文稿的扁平 XML 变体，把整个文档存为单个纯文本 XML 文件而非 ZIP 包。', traits: ['纯文本', '可编辑', '未压缩'], layout: '纯文本，无二进制签名，通常以 XML 声明与 office:document 根元素开头，根元素上的 office:mimetype 属性标明演示文稿类型；正文由 office:body 与 draw:page 等元素描述，样式内联在同一文件中，编码 UTF-8。' },
    en: { summary: 'Flat XML variant of OpenDocument Presentation that keeps the whole document in one plain-text XML file instead of a ZIP package, which eases version control and diffing.', traits: ['Plain text', 'Editable', 'Uncompressed'], layout: 'Plain text with no binary signature, normally opening with an XML declaration and an office:document root element whose office:mimetype attribute marks it as a presentation; the body is described by office:body and draw:page elements with styles inlined in the same file, encoded as UTF-8.' },
  },
  'fods': {
    zh: { summary: 'OpenDocument 电子表格的扁平 XML 变体，单文件纯文本保存工作表、单元格数据与公式。', traits: ['纯文本', '可编辑', '未压缩'], layout: '纯文本，无二进制签名。根元素为 office:document，携带 office:mimetype 指明电子表格；内容分 office:body、office:spreadsheet 与 table:table 等层级，单元格以 table:table-cell 表示。' },
    en: { summary: 'Flat XML variant of OpenDocument Spreadsheet storing sheets, cell data and formulas as a single plain-text file, so no ZIP unpacking is needed to read or diff it.', traits: ['Plain text', 'Editable', 'Uncompressed'], layout: 'Plain text with no binary signature. The root element is office:document with office:mimetype marking it as a spreadsheet; content nests through office:body, office:spreadsheet and table:table, cells are table:table-cell elements with values and formulas in attributes, and style and font tables live in the same file.' },
  },
  'fodt': {
    zh: { summary: 'OpenDocument 文本文档的扁平 XML 变体，把段落、样式与内嵌对象写在单个纯文本 XML 里。', traits: ['纯文本', '可编辑', '未压缩'], layout: '纯文本，无二进制签名。以 XML 声明与 office:document 根元素开头，office:mimetype 标明文本文档类型，正文位于 office:body 与 office:text 之下，段落用 text:p、标题用 text:h。' },
    en: { summary: 'Flat XML variant of OpenDocument Text that writes paragraphs, styles and embedded objects into one plain-text XML file, which suits scripting and version control.', traits: ['Plain text', 'Editable', 'Uncompressed'], layout: 'Plain text with no binary signature. It opens with an XML declaration and an office:document root whose office:mimetype marks a text document, the body sits under office:body and office:text, paragraphs use text:p and headings text:h, and style definitions live in the same file under office:automatic-styles.' },
  },
  'gif': {
    zh: { summary: '索引调色板位图格式，单帧最多 256 色，用 LZW 无损压缩；支持多帧动画与 1 位透明。', traits: ['位图', '支持动画', '支持透明', '无损', '压缩'], layout: '以 6 字节 ASCII 签名 GIF87a 或 GIF89a 开头，随后是逻辑屏幕描述符与可选的全局调色板；之后是块序列，扩展块（图形控制、注释、应用）以 21 引入，图像块以 2C 引入并带局部调色板，像素用 LZW 压缩，文件以 3B 结束。' },
    en: { summary: 'Indexed palette raster format with at most 256 colours per frame and LZW lossless compression; it supports multi-frame animation and 1-bit transparency, and dominated early web icons and reaction images.', traits: ['Raster', 'Animation', 'Alpha', 'Lossless', 'Compressed'], layout: 'Starts with the 6-byte ASCII signature GIF87a or GIF89a, then a logical screen descriptor and an optional global colour table; blocks follow, extensions (graphic control, comment, application) introduced by 21 and image blocks by 2C with an optional local colour table, pixels LZW-compressed, and the file ends with 3B.' },
  },
  'gz': {
    zh: { summary: 'gzip 压缩流，通常由 gzip 或 zlib 工具生成，只有一个成员。', traits: ['压缩', '无损', '流式', '元数据'], layout: '以 3 字节 1F 8B 08 开头（魔数加压缩方法），随后是标志字节、4 字节修改时间、压缩级别提示与操作系统标识；标志位可再带原始文件名、注释与头 CRC，之后是 DEFLATE 数据流，末尾为 4 字节 CRC32 与 4 字节原始长度。' },
    en: { summary: 'gzip compressed stream, usually produced by the gzip or zlib tools, holding a single member; it DEFLATEs the data and records the original size and checksum, and is often paired with tar as tgz.', traits: ['Compressed', 'Lossless', 'Streamable', 'Metadata'], layout: 'Starts with the three bytes 1F 8B 08 (magic plus compression method), then a flag byte, a 4-byte modification time, a compression level hint and an operating system id; flags may add the original file name, a comment and a header CRC, after which comes the DEFLATE stream and finally a 4-byte CRC32 and 4-byte original length.' },
  },
  'gzip': {
    zh: { summary: 'gzip 格式的规范写法，用于单文件压缩与 HTTP 内容编码；基于 DEFLATE 算法，可无损还原。', traits: ['压缩', '无损', '流式'], layout: '固定 10 字节头以 1F 8B 08 开始，依次为标志、修改时间、额外标志与操作系统；可选字段包括原始名、注释与 2 字节头校验；压缩体为 DEFLATE 比特流，尾部 8 字节保存 CRC32 与原始数据长度，多个成员可以首尾拼接。' },
    en: { summary: 'Canonical spelling of the gzip format for single-file compression and HTTP content encoding; it is DEFLATE-based, restores data losslessly and carries a CRC32 check, while multiple files must be archived first.', traits: ['Compressed', 'Lossless', 'Streamable'], layout: 'A fixed 10-byte header begins with 1F 8B 08, followed by flags, modification time, extra flags and operating system; optional fields cover the original name, a comment and a 2-byte header CRC; the payload is a DEFLATE bit stream and the final 8 bytes hold the CRC32 and original length, with members allowed to concatenate.' },
  },
  'hdr': {
    zh: { summary: 'Radiance RGBE 高动态范围图像，用 8 位指数与三个 8 位尾数表示宽亮度范围；头为文本，像素可游程压缩。', traits: ['位图', '无损', '元数据'], layout: '开头是 ASCII 头，首行通常是 #?RADIANCE 或 #?RGBE，接着若干 变量 = 值 行如 FORMAT=32-bit_rle_rgbe；空行后是分辨率行（例如 -Y 1024 +X 2048），随后是扫描线。' },
    en: { summary: 'Radiance RGBE high dynamic range image that encodes a wide luminance range with an 8-bit shared exponent and three 8-bit mantissas; the header is text and pixels may be run-length coded, which makes it popular for HDR environment maps.', traits: ['Raster', 'Lossless', 'Metadata'], layout: 'An ASCII header comes first, its first line usually #?RADIANCE or #?RGBE, followed by variable = value lines such as FORMAT=32-bit_rle_rgbe; after a blank line sits the resolution line (for example -Y 1024 +X 2048) and then the scanlines, stored as plain RGBE quads when the width is under 8 or over 32767 and otherwise in the modern run-length form opened by 2 2 plus width and height.' },
  },
  'heif': {
    zh: { summary: '高效图像文件格式，基于 ISO 基础媒体文件格式，用 HEVC 编码图像；支持 10 位、HDR、缩略图。', traits: ['容器', '有损', '无损', '压缩', '元数据'], layout: '盒式结构，以 ftyp 盒开头，品牌常见 heic、heix 或 mif1；meta 盒保存图像空间，其中 iinf 列出图像项、iloc 给出数据位置、iprp 给出 hvcC 编码配置与色彩信息，实际码流放在 mdat 盒中，缩略图也作为独立图像项。' },
    en: { summary: 'High Efficiency Image File Format based on the ISO base media file format, coding images with HEVC; it supports 10-bit depth, HDR, thumbnails, image collections and sequences, and is the default photo format on Apple devices.', traits: ['Container', 'Lossy', 'Lossless', 'Compressed', 'Metadata'], layout: 'Box structure opening with ftyp, whose brand is usually heic, heix or mif1; a meta box holds the image space, where iinf lists image items, iloc gives data locations and iprp carries hvcC coding configuration and colour information, the actual bitstream lives in mdat, and thumbnails are separate image items.' },
  },
  'html': {
    zh: { summary: '超文本标记语言的网页源文件，纯文本加标签描述结构与链接，由浏览器解析渲染；可内嵌 CSS 与脚本。', traits: ['纯文本', '可编辑', '未压缩'], layout: '纯文本，无二进制签名。开头可选 UTF-8 BOM 与 <!DOCTYPE html> 声明，正文是嵌套的标签树，属性写成 名称="值"；字符编码由 meta charset、HTTP 头或 BOM 决定，换行 LF 或 CRLF 均可，实体如 &amp; 用于转义。' },
    en: { summary: 'HyperText Markup Language source file for web pages: plain text with tags describing structure and links, parsed and rendered by browsers; CSS and scripts can be embedded and the encoding is declared or taken from a BOM.', traits: ['Plain text', 'Editable', 'Uncompressed'], layout: 'Plain text with no binary signature. An optional UTF-8 BOM and a <!DOCTYPE html> declaration come first, the body is a nested tag tree with name="value" attributes, the character encoding comes from a meta charset tag, an HTTP header or a BOM, line endings may be LF or CRLF, and entities such as &amp; escape reserved characters.' },
  },
  'icns': {
    zh: { summary: 'Apple 的图标资源容器，可在一个文件内保存同一图标的多种尺寸与色深；macOS 应用图标使用。', traits: ['位图', '容器', '支持透明', '元数据'], layout: '以 4 字节魔数 69 63 6E 73 开头，即字符 icns，随后 4 字节大端总长度；之后是若干图像块，每块 4 字节类型标识（如 ic07、ic08、ic09 分别对应 128、256、512 像素）加 4 字节块长度，负载为 PNG 或带 alpha 的原始像素。' },
    en: { summary: 'Apple icon resource container that keeps several sizes and colour depths of one icon in a single file; it is used for macOS application icons and its entries are mostly PNG or raw bitmaps.', traits: ['Raster', 'Container', 'Alpha', 'Metadata'], layout: 'Starts with the 4-byte magic 69 63 6E 73, the characters icns, then a 4-byte big-endian total length; image chunks follow, each with a 4-byte type tag (ic07, ic08 and ic09 map to 128, 256 and 512 pixels) and a 4-byte chunk length, holding PNG or raw pixels with alpha.' },
  },
  'ico': {
    zh: { summary: 'Windows 图标格式，一个文件可包含多尺寸与多色深，由系统按显示场景挑选；支持 32 位 alpha。', traits: ['位图', '支持透明', '元数据'], layout: '以 6 字节 ICONDIR 开头：保留字段 00 00、类型 01 00 表示图标、2 字节图像数量；随后每图一个 16 字节目录项，给出宽高、色数、位面、位深与负载大小及偏移；负载是带 AND 掩码的 DIB，或对 256 像素及以上用 PNG。' },
    en: { summary: 'Windows icon format that can hold several sizes and colour depths in one file for the system to pick per context; it supports 32-bit alpha and each entry is a BMP or an embedded PNG.', traits: ['Raster', 'Alpha', 'Metadata'], layout: 'Opens with a 6-byte ICONDIR: reserved 00 00, type 01 00 for icons and a 2-byte image count; each image then has a 16-byte directory entry giving width, height, colour count, planes, bit depth plus payload size and offset; the payload is a DIB with an AND mask, or a PNG for 256-pixel and larger entries.' },
  },
  'ipynb': {
    zh: { summary: 'Jupyter Notebook 文档，用 JSON 纯文本保存代码单元、标记说明与执行输出。', traits: ['纯文本', '可编辑', '元数据'], layout: '纯文本 JSON，无二进制签名。顶层键包括 nbformat、nbformat_minor、metadata 与 cells 数组；每个单元有 cell_type（code、markdown 或 raw）、source 字符串数组。' },
    en: { summary: 'Jupyter Notebook document that stores code cells, markdown prose and execution outputs as plain-text JSON, with rich outputs embedded as base64; it eases version control and sharing of analysis.', traits: ['Plain text', 'Editable', 'Metadata'], layout: 'Plain-text JSON with no binary signature. Top-level keys are nbformat, nbformat_minor, metadata and a cells array; each cell has a cell_type (code, markdown or raw) and a source array of strings, code cells add execution_count and outputs, and rich output such as images is embedded as base64 strings.' },
  },
  'iso': {
    zh: { summary: '光盘镜像文件，通常按 ISO 9660 文件系统保存整张光盘内容，也常见 UDF 桥接；用于分发操作系统与软件。', traits: ['容器', '未压缩', '元数据'], layout: '前 16 个扇区（共 32 KB）为系统区，可写入 El Torito 引导代码；主卷描述符从第 16 扇区开始，结构以 1 字节类型、5 字节标识 CD001 与版本字节开头，记录卷大小、根目录记录、路径表位置；之后是目录记录与按逻辑块排列的文件数据。' },
    en: { summary: 'Optical disc image that normally holds a whole disc in the ISO 9660 file system, often bridged with UDF; it is used to distribute operating systems and software and can be mounted or written to media directly.', traits: ['Container', 'Uncompressed', 'Metadata'], layout: 'The first 16 sectors (32 KB) form the system area and may hold El Torito boot code; volume descriptors start at sector 16 with a 1-byte type, the 5-byte identifier CD001 and a version byte, recording volume size, the root directory record and path table locations, after which come directory records and file data in logical blocks.' },
  },
  'j2k': {
    zh: { summary: 'JPEG 2000 的裸码流形式，不含容器包装；用离散小波变换与基于上下文的算术编码，支持有损与无损。', traits: ['位图', '有损', '无损', '压缩'], layout: '码流由标记段组成，以 2 字节 SOC 标记 FF 4F 开头，随后 SIZ 给出图像与分块尺寸、COD 给出编码风格、QCD 给出量化步长，之后是按 tile-part 划分的压缩数据，最后以 2 字节 EOC 标记 FF D9 结束。' },
    en: { summary: 'Raw codestream form of JPEG 2000 without any container wrapper; it uses a discrete wavelet transform with context-based arithmetic coding and supports lossy or lossless coding, progressive delivery and regions of interest.', traits: ['Raster', 'Lossy', 'Lossless', 'Compressed'], layout: 'The codestream is a sequence of marker segments starting with the 2-byte SOC marker FF 4F, followed by SIZ for image and tile sizes, COD for the coding style and QCD for quantisation steps, then compressed data split into tile-parts, and it ends with the 2-byte EOC marker FF D9.' },
  },
  'jar': {
    zh: { summary: 'Java 归档文件，本质是 ZIP 包，装编译后的类文件、资源与清单；JVM 直接读取，可带数字签名以校验来源与完整性。', traits: ['压缩', '无损', '容器', '元数据'], layout: 'ZIP 结构，以本地文件头 50 4B 03 04 开头，惯例把 META-INF/MANIFEST.MF 放在最前，其中有 Main-Class 等属性；类文件位于包路径对应目录，签名信息存于 META-INF 下的 .SF、.RSA 或 .DSA 文件。' },
    en: { summary: 'Java archive, essentially a ZIP package holding compiled classes, resources and a manifest; the JVM reads it directly and it can carry digital signatures that verify origin and integrity.', traits: ['Compressed', 'Lossless', 'Container', 'Metadata'], layout: 'ZIP structure starting with the local file header 50 4B 03 04, conventionally placing META-INF/MANIFEST.MF first with attributes such as Main-Class; class files sit under directories matching their package paths, signature data lives in .SF, .RSA or .DSA files under META-INF, and the central directory and end record close the file.' },
  },
  'jp2': {
    zh: { summary: 'JPEG 2000 的 ISO 基盒容器封装，比裸码流多出色彩空间与分辨率信息；支持有损与无损压缩、渐进解码和高位深。', traits: ['位图', '有损', '无损', '压缩', '容器'], layout: '以 12 字节签名盒开头：长度 00 00 00 0C 加类型 6A 50 20 20 与内容 0D 0A 87 0A；随后是 ftyp 盒（品牌 jp2 ）、jp2h 头盒（内含 ihdr 图像头与 colr 色彩盒），最后 jp2c 盒装载 JPEG 2000 码流。' },
    en: { summary: 'JPEG 2000 wrapped in the ISO base media box container, adding colour space and resolution information over the raw codestream; it supports lossy and lossless coding, progressive decoding and high bit depths, and is widely used for image archiving.', traits: ['Raster', 'Lossy', 'Lossless', 'Compressed', 'Container'], layout: 'Opens with a 12-byte signature box: length 00 00 00 0C plus type 6A 50 20 20 and content 0D 0A 87 0A; an ftyp box (brand jp2) follows together with a jp2h header box holding ihdr image header and colr colour boxes, and a jp2c box finally carries the JPEG 2000 codestream, all big-endian.' },
  },
  'jpg': {
    zh: { summary: '最通用的有损照片格式，用离散余弦变换与量化丢弃高频细节，压缩率高、兼容性极佳；不支持透明，反复保存会累积损失。', traits: ['有损', '位图', '压缩', '元数据'], layout: '以 SOI 标记 FF D8 开头，随后是若干以 FF 加标记码引导、带 2 字节长度的段（APP0 的 JFIF、APP1 的 Exif、DQT 量化表、SOF 帧头、DHT 霍夫曼表），压缩数据在 SOS 段之后按 MCU 排列，最后以 EOI 标记 FF D9 结束。' },
    en: { summary: 'The most widely used lossy photo format; it discards high-frequency detail through a discrete cosine transform and quantisation, giving strong compression and excellent compatibility, but no transparency and cumulative loss on repeated saves.', traits: ['Lossy', 'Raster', 'Compressed', 'Metadata'], layout: 'Starts with the SOI marker FF D8, then segments each introduced by FF plus a marker code and a 2-byte length (APP0 for JFIF, APP1 for Exif, DQT quantisation tables, SOF frame header, DHT Huffman tables); compressed data follows the SOS segment in MCU order and the file ends with the EOI marker FF D9.' },
  },
  'json': {
    zh: { summary: '轻量数据交换格式，用对象、数组与基本类型表达结构化数据；语法简单、语言中立，是配置文件与接口响应的主流选择。', traits: ['纯文本', '可编辑', '未压缩'], layout: '纯文本，无二进制签名。规范要求以 UTF-8 编码且不应带 BOM；顶层是对象或数组，成员写成 名称: 值，字符串用双引号并支持反斜杠转义，数字不含前导零也不允许注释与尾随逗号。逐行变体常用扩展名 jsonl。' },
    en: { summary: 'Lightweight data interchange format that expresses structured data with objects, arrays and primitive types; the simple, language-neutral syntax makes it the default for configuration files and API responses.', traits: ['Plain text', 'Editable', 'Uncompressed'], layout: 'Plain text with no binary signature. The specification requires UTF-8 and discourages a BOM; the top level is an object or array, members are written as name: value, strings use double quotes with backslash escapes, and numbers carry no leading zeros while comments and trailing commas are forbidden. A line-delimited variant often uses the jsonl extension.' },
  },
  'latex': {
    zh: { summary: 'LaTeX 排版系统的纯文本源文件，用反斜杠命令与花括号参数描述文档结构与数学公式；由引擎编译成 DVI 或 PDF。', traits: ['纯文本', '可编辑', '多页'], layout: '纯文本，无二进制签名。文档以 documentclass 声明开始，导言区放宏包与自定义命令，正文位于 begin{document} 与 end{document} 之间；命令以反斜杠引导，参数在花括号内，数学环境用美元符号或方括号区分行内与行间公式，注释以百分号开始。' },
    en: { summary: 'Plain-text source for the LaTeX typesetting system, using backslash commands and brace-delimited arguments to describe document structure and mathematics; an engine compiles it to DVI or PDF, which suits scientific papers.', traits: ['Plain text', 'Editable', 'Multi-page'], layout: 'Plain text with no binary signature. A document opens with a documentclass declaration, the preamble holds packages and custom commands, and the body sits between begin and end document calls; commands start with a backslash, arguments are braced, math uses dollar signs or brackets for inline versus display formulas, and comments begin with a percent sign.' },
  },
  'm4a': {
    zh: { summary: 'MP4 容器中的纯音频文件，苹果生态常用；音频可为有损的 AAC 或无损的 ALAC，支持章节、封面与元数据标签。', traits: ['容器', '有损', '无损', '压缩', '元数据'], layout: '与 MP4 相同，是盒式结构：ftyp 盒的品牌为 M4A 或 mp42，moov 盒中的轨道只含音频样本条目（mp4a 或 alac），样本表给出时长与偏移，音频数据放在 mdat 盒；iTunes 风格的元数据存于 moov 下的 udta 与 meta 盒中。' },
    en: { summary: 'Audio-only file in the MP4 container, common throughout the Apple ecosystem; the audio can be lossy AAC or lossless ALAC and the file supports chapters, cover art and metadata tags.', traits: ['Container', 'Lossy', 'Lossless', 'Compressed', 'Metadata'], layout: 'Same as MP4, a box structure: the ftyp brand is M4A or mp42, the moov box holds a track with only an audio sample entry (mp4a or alac), sample tables give durations and offsets, and audio data sits in mdat; iTunes-style metadata lives in udta and meta boxes inside moov.' },
  },
  'magick': {
    zh: { summary: 'ImageMagick 原生图像格式在部分工具中的名称，与 MIFF 同族；适合保存中间结果，可保留蒙版与多帧。', traits: ['位图', '无损', '压缩', '元数据'], layout: '文件头为 ASCII 键值对，首行为 id=ImageMagick，随后是 class、colorspace、columns、rows、depth、compression 等字段，每项一行；头部以冒号结束，其后是像素数据，可按需采用 RLE、Zip、BZip 或 JPEG 压缩。' },
    en: { summary: 'Format name used by some tools for the ImageMagick native image format, in the same family as MIFF; it suits intermediate results because it can preserve masks, multiple frames and colour profiles.', traits: ['Raster', 'Lossless', 'Compressed', 'Metadata'], layout: 'The header is a list of ASCII key-value pairs, the first line reading id=ImageMagick, followed by one line each for class, colorspace, columns, rows, depth and compression; the header ends with a colon and pixel data comes next, optionally compressed with RLE, Zip, BZip or JPEG, so it can be lossless or lossy.' },
  },
  'man': {
    zh: { summary: 'Unix 手册页的 troff 源文件，纯文本加行首宏命令描述标题、段落与字体；由 man 或 mandoc 渲染。', traits: ['纯文本', '可编辑', '多页'], layout: '纯文本，无二进制签名。行首的宏控制结构，常用 TH 定义标题与章节，SH 与 SS 开小节，P 起段落，B 与 I 切换粗体斜体；反斜杠引导转义，行首的点号表示宏调用，注意行首点号单独一行表示段落结束。' },
    en: { summary: 'troff source for Unix manual pages: plain text with leading macro calls describing titles, sections and font changes; man or mandoc renders it, and the extension follows the section number such as 1, 5 or 8.', traits: ['Plain text', 'Editable', 'Multi-page'], layout: 'Plain text with no binary signature. Macros at the start of a line drive the structure: TH defines the title and section, SH and SS open sections, P starts a paragraph, and B and I switch bold or italic; backslashes introduce escapes, a leading dot marks a macro call, and a lone dot on its own line ends a paragraph.' },
  },
  'markdown': {
    zh: { summary: '面向可读性的轻量标记语言，用井号、星号与竖线等符号表达标题、强调、列表与表格，常渲染为 HTML。', traits: ['纯文本', '可编辑', '未压缩'], layout: '纯文本，无二进制签名。井号加空格开标题，星号或下划线包裹表示强调，减号、加号或数字加点构成列表，反引号围栏放代码，竖线与连字符画表格，方括号与圆括号构成链接；规范在 CommonMark 中定义，文件一般为 UTF-8 与 LF 换行，扩展名 md 已规范化为 markdown。' },
    en: { summary: 'Lightweight markup language designed to stay readable, using hashes, asterisks and pipes for headings, emphasis, lists and tables; it is usually rendered to HTML and is everywhere in documentation and readme files.', traits: ['Plain text', 'Editable', 'Uncompressed'], layout: 'Plain text with no binary signature. A hash plus a space opens a heading, asterisks or underscores wrap emphasis, hyphens, plus signs or numbered dots form lists, backtick fences hold code, pipes and hyphens draw tables, and brackets with parentheses form links; CommonMark defines the syntax, files are normally UTF-8 with LF endings, and the md extension is normalised to markdown.' },
  },
  'mediawiki': {
    zh: { summary: 'MediaWiki 维基文本，纯文本加专属标记表达标题、链接、模板与表格；由 wiki 引擎解析成 HTML。', traits: ['纯文本', '可编辑', '未压缩'], layout: '纯文本，无二进制签名。标题用两侧等号数量分级，内部链接写在双方括号里并可加竖线别名，外部链接用单方括号，模板调用写在双方括号内并把页面名放在花括号中，表格以花括号加竖线开启；行首符号表示列表与缩进，冒号用于缩进。' },
    en: { summary: 'MediaWiki wikitext: plain text with bespoke markup for headings, links, templates and tables, parsed into HTML by the wiki engine; it is easy to edit but the syntax is unique to that platform.', traits: ['Plain text', 'Editable', 'Uncompressed'], layout: 'Plain text with no binary signature. Heading level comes from the number of equals signs on each side, internal links sit in double square brackets with an optional pipe alias, external links use single brackets, template calls place the page name in double braces, and tables start with braces plus a pipe; leading characters mark lists and indentation, with colons for indents.' },
  },
  'miff': {
    zh: { summary: 'ImageMagick 的原生图像文件格式，用文本头描述图像参数再跟像素数据；能保存多帧、蒙版与色彩配置。', traits: ['位图', '无损', '压缩', '元数据'], layout: '头部是若干行 ASCII 键值对，首行形如 id=ImageMagick，其中有 class、colorspace、columns、rows、depth 与 compression；头部以冒号结束，其后是像素数据，可按 RLE、Zip 或 BZip 压缩。' },
    en: { summary: 'Native image file format of ImageMagick, using a text header for image parameters before the pixel data; it can store multiple frames, masks and colour profiles, which makes it handy as an intermediate in processing pipelines.', traits: ['Raster', 'Lossless', 'Compressed', 'Metadata'], layout: 'The header is several lines of ASCII key-value pairs whose first line looks like id=ImageMagick and which cover class, colorspace, columns, rows, depth, compression and optional profile references; the header ends with a colon, pixel data follows, and compression may be none, RLE, Zip, BZip or JPEG, with a zero character padding the end.' },
  },
  'mkv': {
    zh: { summary: 'Matroska 开放容器，基于 EBML 可扩展二进制元语言；可在同一文件里放多条音视频与字幕轨道、章节和附件。', traits: ['容器', '压缩', '流式', '元数据'], layout: '以 EBML 头开始，魔数为 1A 45 DF A3，头内 DocType 为 matroska（WebM 则为 webm）；其后是 Segment 元素，内含 Info（时长与时基）、Tracks（各轨道编码参数）。' },
    en: { summary: 'Matroska open container built on the EBML extensible binary meta language; one file can hold several audio, video and subtitle tracks plus chapters and attachments, making it a common wrapper for distribution and archiving.', traits: ['Container', 'Compressed', 'Streamable', 'Metadata'], layout: 'Starts with an EBML header whose magic is 1A 45 DF A3 and whose DocType is matroska (webm for WebM); a Segment element follows, containing Info (duration and timecode scale), Tracks (codec parameters per track), Clusters (timecode-organised SimpleBlocks) and optional Chapters, Attachments and Cues indexes.' },
  },
  'mng': {
    zh: { summary: '多图像网络图形格式，把若干 PNG 图像与帧控制块放进一个文件实现动画，还允许嵌入 JPEG。', traits: ['位图', '支持动画', '支持透明', '无损', '压缩'], layout: '以 8 字节签名 8A 4D 4E 47 0D 0A 1A 0A 开头，与 PNG 只差首字节；其后是与 PNG 类似的块序列，每块为 4 字节长度、4 字节类型与数据再加 4 字节 CRC，以 MHDR 开头，用 FRAM、MOVE 等块控制动画帧，MEND 结束。' },
    en: { summary: 'Multiple-image Network Graphics, which puts several PNG images with frame control chunks into one file to produce animation and may also embed JPEG data; poor support let GIF and WebP replace it.', traits: ['Raster', 'Animation', 'Alpha', 'Lossless', 'Compressed'], layout: 'Starts with the 8-byte signature 8A 4D 4E 47 0D 0A 1A 0A, differing from PNG in the first byte only; a PNG-like chunk sequence follows, each chunk being a 4-byte length, 4-byte type and data plus a 4-byte CRC, opened by MHDR, driving animation frames with FRAM and MOVE chunks, and closed by MEND.' },
  },
  'mov': {
    zh: { summary: 'Apple QuickTime 影片容器，是 ISO 基础媒体文件格式的前身；用盒（atom）组织媒体数据与元信息。', traits: ['容器', '有损', '压缩', '元数据'], layout: '同为盒式结构，每个盒以 4 字节大端长度与 4 字节类型开头；典型排列是 ftyp（品牌 qt ）、moov（轨道、时间与样本表）、mdat（媒体数据）以及可选的 free 与 wide 填充盒，还可把 moov 拆到独立的引用影片文件中。' },
    en: { summary: 'Apple QuickTime movie container and the ancestor of the ISO base media file format; boxes (atoms) organise media data and metadata, and it remains widespread in professional editing workflows.', traits: ['Container', 'Lossy', 'Compressed', 'Metadata'], layout: 'Also a box structure, each box opening with a 4-byte big-endian length and a 4-byte type; the typical order is ftyp (brand qt), moov (tracks, timing and sample tables), mdat (media data) plus optional free and wide padding boxes, and moov may be split into a separate reference movie file.' },
  },
  'mp3': {
    zh: { summary: 'MPEG-1/2 第三层音频编码，用改良离散余弦变换与霍夫曼编码做有损压缩；兼容性极强，是便携播放器时代的通用音乐格式。', traits: ['有损', '压缩', '元数据', '流式'], layout: '常见以 ID3v2 标签开头，前 3 字节为 49 44 33 即 ID3，标签后是连续帧，每帧以 11 位同步字 FF E 开头，帧头含版本、层、码率与采样率索引；文件尾常有 128 字节 ID3v1 标签，以 ASCII 的 TAG 开头。' },
    en: { summary: 'MPEG-1 and MPEG-2 Audio Layer III, a lossy codec using a modified discrete cosine transform plus Huffman coding; its ubiquity made it the default music format of the portable player era.', traits: ['Lossy', 'Compressed', 'Metadata', 'Streamable'], layout: 'It often begins with an ID3v2 tag whose first three bytes are 49 44 33, the characters ID3, followed by consecutive frames each starting with the 11-bit sync word FF E and a header carrying version, layer, bitrate and sample-rate index; a 128-byte ID3v1 tag beginning with the ASCII text TAG frequently closes the file.' },
  },
  'mp4': {
    zh: { summary: '基于 ISO 基础媒体文件格式的通用容器，封装 H.264、H.265、AAC 等编码；支持流式播放、片段化封装。', traits: ['容器', '有损', '压缩', '流式', '元数据'], layout: '盒式结构，每盒 4 字节大端长度加 4 字节类型；典型为 ftyp（品牌 isom、mp42 等）、moov（轨道信息与 stbl 样本表，描述每帧偏移、大小与时间）、mdat（媒体数据），片段化时可加 moof 与 mfra 盒以便流式分发。' },
    en: { summary: 'General-purpose container based on the ISO base media file format that wraps H.264, H.265, AAC and similar codecs; it supports streaming playback, fragmented packaging, subtitles and metadata, and dominates online video.', traits: ['Container', 'Lossy', 'Compressed', 'Streamable', 'Metadata'], layout: 'Box structure where each box is a 4-byte big-endian length plus a 4-byte type; the usual set is ftyp (brands such as isom or mp42), moov (track information and stbl sample tables giving each frame offset, size and time) and mdat (media data), with moof and mfra boxes added when fragmented for streaming.' },
  },
  'mpeg': {
    zh: { summary: 'MPEG-1 与 MPEG-2 的系统层封装，把有损压缩的视频与音频复用成单一数据流；用于旧式光盘、数字电视与 DVD。', traits: ['容器', '有损', '压缩', '流式'], layout: '由起始码引导：每组数据以 3 字节前缀 00 00 01 加 1 字节流标识开头，系统层用 BA 表示包起始并携带时间戳，节目流用 BC，之后是 PES 包；视频按 GOP 与图像序列组织，音频为 MPEG 音频帧，节目流还含节目流映射表。' },
    en: { summary: 'System layer of MPEG-1 and MPEG-2 that multiplexes lossy-compressed video and audio into one stream; it served early optical media, digital television and DVD with excellent compatibility but lower efficiency than newer formats.', traits: ['Container', 'Lossy', 'Compressed', 'Streamable'], layout: 'Driven by start codes: each unit begins with the 3-byte prefix 00 00 01 plus a 1-byte stream identifier, the system layer uses BA for a pack header carrying timestamps and BC for program streams, and PES packets follow; video is organised into GOPs and picture sequences, audio into MPEG audio frames, and program streams add a program stream map.' },
  },
  'mpo': {
    zh: { summary: '多图像格式，把多张 JPEG 串成一个文件供立体相机与手机双摄保存左右视图；首图为普通 JPEG，兼容老软件。', traits: ['位图', '有损', '多页', '元数据'], layout: '文件是一系列完整 JPEG 的拼接，以 FF D8 开始、FF D9 结束；第二个 JPEG 之前插入 APP2 段（标记 FF E2）并带 MPF 标识 4D 50 46 00，其中 MP Index IFD 列出图像数量以及每张图的相对偏移与大小，第一张图为主图。' },
    en: { summary: 'Multi-Picture Format, which chains several JPEG images into one file so stereo cameras and dual-lens phones can store left and right views; the first image is a normal JPEG that old software reads, while an index segment points at the extras.', traits: ['Raster', 'Lossy', 'Multi-page', 'Metadata'], layout: 'The file is a concatenation of complete JPEGs, each starting with FF D8 and ending with FF D9; an APP2 segment (marker FF E2) carrying the MPF identifier 4D 50 46 00 precedes the second JPEG, and its MP Index IFD lists the image count plus each image relative offset and size, with the first image acting as the primary one.' },
  },
  'native': {
    zh: { summary: 'ImageMagick 原生图像格式（即 MIFF）的别名，用文本头加二进制像素保存图像；支持多帧与蒙版。', traits: ['位图', '无损', '压缩', '元数据'], layout: '文件头为 ASCII 键值对，首行标识为 id=ImageMagick，逐行给出 class、colorspace、columns、rows、depth 与 compression 等参数，可选 profile 以文件名引用外部数据；头部以冒号行结束，之后是像素数据。' },
    en: { summary: 'Alias for the ImageMagick native image format, that is MIFF, storing images as a text header plus binary pixels; it supports multiple frames and masks, and is often used for temporary files inside batch pipelines.', traits: ['Raster', 'Lossless', 'Compressed', 'Metadata'], layout: 'The header consists of ASCII key-value pairs identified by a first line of id=ImageMagick, with lines giving class, colorspace, columns, rows, depth and compression, and optional profiles referenced by file name; a colon line ends the header, pixel data follows, and compression may be RLE, Zip, BZip or none.' },
  },
  'odp': {
    zh: { summary: 'OpenDocument 演示文稿，ZIP 包内用 XML 描述幻灯片、母版与动画，格式开放且可加密。', traits: ['压缩', '容器', '可编辑', '多页', '元数据'], layout: 'ZIP 容器，首个条目必须是 mimetype 且以存储方式未压缩保存，内容为 application/vnd.oasis.opendocument.presentation；随后 META-INF/manifest.xml 列出部件，content.xml 保存幻灯片与页面。' },
    en: { summary: 'OpenDocument Presentation, supported by LibreOffice and most office suites; inside the ZIP package, XML describes slides, masters and animations, the whole file can be encrypted, and the format is openly specified.', traits: ['Compressed', 'Container', 'Editable', 'Multi-page', 'Metadata'], layout: 'A ZIP container whose first entry must be mimetype stored uncompressed and containing application/vnd.oasis.opendocument.presentation; META-INF/manifest.xml then lists the parts, content.xml holds slides and pages, styles.xml holds styles, meta.xml holds metadata, and images live in the Pictures directory.' },
  },
  'ods': {
    zh: { summary: 'OpenDocument 电子表格，用 XML 描述工作表、单元格、公式与图表。', traits: ['压缩', '容器', '可编辑', '元数据'], layout: 'ZIP 容器，mimetype 条目未压缩保存，内容为 application/vnd.oasis.opendocument.spreadsheet；content.xml 用 table:table 表示工作表，table:table-cell 表示单元格并带公式。' },
    en: { summary: 'OpenDocument Spreadsheet, using XML to describe sheets, cells, formulas and charts; LibreOffice and Excel both read it widely, and the format is open and encryptable.', traits: ['Compressed', 'Container', 'Editable', 'Metadata'], layout: 'A ZIP container whose mimetype entry is stored first and uncompressed, containing application/vnd.oasis.opendocument.spreadsheet; in content.xml, table:table elements represent sheets and table:table-cell elements represent cells with formula and type attributes, styles.xml and meta.xml hold styling and metadata, and repeated values collapse into row or column spans.' },
  },
  'odt': {
    zh: { summary: 'OpenDocument 文本文档，用 XML 保存段落、样式、表格与图像，支持修订、批注与数字签名。', traits: ['压缩', '容器', '可编辑', '多页', '元数据'], layout: 'ZIP 容器，首个条目为未压缩的 mimetype，内容 application/vnd.oasis.opendocument.text；content.xml 保存 office:text 正文，styles.xml 保存命名样式与页面设置，meta.xml 保存作者与时间。' },
    en: { summary: 'OpenDocument Text, storing paragraphs, styles, tables and images as XML and supporting change tracking, comments and digital signatures; it is the most common open document format besides docx.', traits: ['Compressed', 'Container', 'Editable', 'Multi-page', 'Metadata'], layout: 'A ZIP container whose first entry is an uncompressed mimetype holding application/vnd.oasis.opendocument.text; content.xml holds the office:text body, styles.xml the named styles and page setup, meta.xml the author and timestamps, settings.xml the view settings, images sit in Pictures, and signatures live under META-INF.' },
  },
  'ogg': {
    zh: { summary: 'Xiph 的开放容器，用页结构承载 Vorbis、Opus、FLAC 或 Theora 等编码；支持流式播放与多路复用。', traits: ['容器', '有损', '无损', '流式', '压缩'], layout: '以 4 字节捕获模式 4F 67 67 53 开头，即字符 OggS；每个页含版本字节、头类型标志、8 字节粒度位置、4 字节流序号、页序号、CRC32 与段表；逻辑流以 BOS 页开始、EOS 页结束，包可跨页续接，首个包内含编码标识与参数。' },
    en: { summary: 'Open container from Xiph that carries Vorbis, Opus, FLAC or Theora payloads in pages; it supports streaming and multiplexing, carries no patent restrictions, and is common in open-source audio and video.', traits: ['Container', 'Lossy', 'Lossless', 'Streamable', 'Compressed'], layout: 'Starts with the 4-byte capture pattern 4F 67 67 53, the characters OggS; each page holds a version byte, header type flags, an 8-byte granule position, a 4-byte stream serial, a page sequence number, a CRC32 and a segment table; logical streams open with a BOS page and close with an EOS page, packets may span pages, and the first packet identifies the codec and its parameters.' },
  },
  'ogv': {
    zh: { summary: 'Ogg 容器中的视频文件，通常视频用 Theora、音频用 Vorbis；完全开放无专利负担。', traits: ['容器', '有损', '压缩', '流式'], layout: '与 Ogg 一致：以 4F 67 67 53 即 OggS 开头，首页为 BOS 并带 Theora 标识头（含宽高与帧率），随后是 Vorbis 音频的标识与注释页；数据页以粒度位置标记时间，最后一页带 EOS 标志，页内包连续存放。' },
    en: { summary: 'Video file in the Ogg container, usually Theora video with Vorbis audio; it is entirely open with no patent burden and saw use in early web video and free software projects.', traits: ['Container', 'Lossy', 'Compressed', 'Streamable'], layout: 'Identical to Ogg: it starts with 4F 67 67 53, the characters OggS, the first page being a BOS page with the Theora identification header (width, height, frame rate), followed by Vorbis identification and comment pages for the audio; data pages mark time through granule positions, the last page carries the EOS flag, and packets sit back to back inside pages.' },
  },
  'opml': {
    zh: { summary: 'XML 大纲格式，用嵌套 outline 元素表达层级列表，最初用于订阅列表交换；结构极简。', traits: ['纯文本', '可编辑', '元数据'], layout: '纯文本，无二进制签名。根元素是 opml，通常带 version 属性为 2.0；内部先有 head 元素存放 title、日期等元数据，再由 body 包裹嵌套的 outline 元素，层级靠嵌套深度表示，条目属性如 text、type、xmlUrl 直接写在标签上。' },
    en: { summary: 'XML outline format that expresses hierarchical lists with nested outline elements, first created to exchange subscription lists; the structure is minimal and it is widely supported by feed readers and outliners.', traits: ['Plain text', 'Editable', 'Metadata'], layout: 'Plain text with no binary signature. The root element is opml, normally with a version attribute of 2.0; a head element carries metadata such as the title and date, then a body wraps nested outline elements whose depth encodes hierarchy, with entry attributes like text, type and xmlUrl written directly on the tags.' },
  },
  'opus': {
    zh: { summary: '交互式语音与音频的有损编码，融合 SILK 与 CELT 两种模式，兼顾语音与音乐；延迟可低至数毫秒。', traits: ['有损', '压缩', '流式'], layout: '编码层本身无固定文件签名，封装进 Ogg 时以 OggS 页开始，首个包含 OpusHead 标识头（版本、声道数、预跳过样本数与采样率），第二个包为 OpusTags 注释；音频包按 2.5 到 60 毫秒的帧组织，帧长由包内首字节的配置字段决定。' },
    en: { summary: 'Lossy codec for interactive speech and audio that combines the SILK and CELT modes, covering both voice and music; latency can drop to a few milliseconds, which makes it the default for real-time calls and web audio.', traits: ['Lossy', 'Compressed', 'Streamable'], layout: 'The codec itself has no file signature, and inside Ogg it starts with an OggS page whose first packet is the OpusHead identification header (version, channel count, pre-skip samples, sample rate) and whose second is an OpusTags comment packet; audio packets hold frames of 2.5 to 60 milliseconds, with frame length set by the configuration field in the first byte.' },
  },
  'org': {
    zh: { summary: 'Org 模式纯文本大纲文件，用星号分级标题、关键词标记待办状态，并可内嵌表格、代码块与时间戳；由 Emacs 解析。', traits: ['纯文本', '可编辑', '未压缩'], layout: '纯文本，无二进制签名。行首一个或多个星号加空格表示标题层级，TODO 与 DONE 等关键词紧随其后；表格以竖线分列，代码与环境块用 #+BEGIN_SRC 与 #+END_SRC 围栏，属性与元信息写成 #+关键字: 值，链接使用双方括号。' },
    en: { summary: 'Plain-text outline file for Org mode, using asterisk-prefixed headings and keywords to mark task states, and able to embed tables, code blocks and timestamps; Emacs parses it and it exports to many formats.', traits: ['Plain text', 'Editable', 'Uncompressed'], layout: 'Plain text with no binary signature. One or more asterisks plus a space at the start of a line give the heading level, with TODO and DONE style keywords right after; tables are pipe-separated, code and environment blocks are fenced by #+BEGIN_SRC and #+END_SRC, properties and metadata are written as keyword lines, and links use double square brackets.' },
  },
  'otb': {
    zh: { summary: 'Nokia 的空中下载位图，单色一位图像格式，用于早期手机通过短信或 WAP 传输小图标与图片；结构极简。', traits: ['位图', '未压缩', '无损'], layout: '无 ASCII 魔数，头部为若干小端字段，记录图像宽高、位置偏移与像素数据长度等信息；其后是位图数据，每行像素按位自左至右打包成一到多个字节，行末不足一字节处补零，没有压缩与校验字段。' },
    en: { summary: 'Nokia over-the-air bitmap, a one-bit monochrome image format used by early phones to transfer small icons and pictures over SMS or WAP; the structure is minimal and black and white pixels are packed by bit.', traits: ['Raster', 'Uncompressed', 'Lossless'], layout: 'There is no ASCII magic; the header is a few little-endian fields recording image width and height, a position offset and the pixel data length, and the bitmap follows, with each row packed bit by bit into one or more bytes and the tail of a row padded with zero bits. No compression or checksum fields exist.' },
  },
  'pbm': {
    zh: { summary: 'Netpbm 家族的黑白位图，仅用一位表示每个像素，无调色板也无灰度；有 ASCII 与二进制两种编码。', traits: ['位图', '未压缩', '无损'], layout: '文件以两字节魔数开头：ASCII 版为 P1，二进制版为 P4；其后以空白分隔给出宽度、高度，可选注释行以井号开始，随后是像素数据，P1 用 0 与 1 的 ASCII 字符逐位写出，P4 则把每行按位打包成一到多个字节。' },
    en: { summary: 'Black and white bitmap from the Netpbm family, using a single bit per pixel with no palette and no grey levels; it comes in ASCII and binary encodings and often serves as simple input for image-processing algorithms.', traits: ['Raster', 'Uncompressed', 'Lossless'], layout: 'The file starts with a two-byte magic: P1 for the ASCII variant and P4 for the binary one; whitespace-separated width and height follow, comment lines may begin with a hash, and then come the pixels, written as ASCII zeros and ones for P1 or packed row by row into bytes for P4.' },
  },
  'pcx': {
    zh: { summary: 'ZSoft 的 PC Paintbrush 位图，用逐字节游程编码压缩，支持 1 到 8 位调色板与 24 位真彩。', traits: ['位图', '无损', '压缩'], layout: '以 1 字节厂商标识 0A 开头，随后是版本、编码方式（1 表示游程编码）、每像素位数与图像的四个边界值，以及调色板信息与保留区，共 128 字节；之后是按平面排列的压缩像素数据，256 色图像在文件末尾附加 0C 标记与 768 字节调色板。' },
    en: { summary: 'Bitmap format created by ZSoft for PC Paintbrush, compressed with byte-oriented run-length encoding and supporting 1 to 8-bit palettes as well as 24-bit true colour; the simple layout made it common in early DOS imaging software.', traits: ['Raster', 'Lossless', 'Compressed'], layout: 'Starts with the one-byte manufacturer id 0A, then version, encoding (1 means run-length), bits per pixel, the four image bounds, palette information and a reserved area, all within a 128-byte header; compressed pixel data follows in planes, and 256-colour files append a 0C marker plus a 768-byte palette at the end.' },
  },
  'pdf': {
    zh: { summary: '便携式文档格式，用与设备无关的方式描述文字、矢量图形与图像，保证跨平台版式一致；支持多页、书签、表单、数字签名与加密。', traits: ['多页', '矢量', '压缩', '元数据', '加密'], layout: '以 7 字节 %PDF- 加版本号开头；主体是若干间接对象（编号、代数与对象内容），流对象可用 FlateDecode 等过滤器压缩，文件尾部有交叉引用表或 xref 流、trailer 字典与 startxref 偏移，并以 %%EOF 结束。' },
    en: { summary: 'Portable Document Format, describing text, vector graphics and images device-independently so layout stays identical across platforms; it supports multiple pages, bookmarks, forms, digital signatures and encryption.', traits: ['Multi-page', 'Vector', 'Compressed', 'Metadata', 'Encrypted'], layout: 'Opens with the seven bytes %PDF- plus a version number; the body is a set of indirect objects (number, generation and content) whose streams may be compressed with filters such as FlateDecode, and the tail holds a cross-reference table or xref stream, a trailer dictionary and a startxref offset, ending with %%EOF.' },
  },
  'pgm': {
    zh: { summary: 'Netpbm 家族的灰度位图，每个像素按最大灰度值决定用 1 或 2 字节；编码简单直观。', traits: ['位图', '未压缩', '无损'], layout: '以两字节魔数开头：ASCII 版为 P2，二进制版为 P5；随后空白分隔给出宽度、高度与最大灰度值，允许井号注释；数据部分 P2 用十进制数值、P5 用大端二进制字节表示每个像素，每行长度与宽度一致，没有额外头或校验。' },
    en: { summary: 'Greyscale bitmap from the Netpbm family whose pixels use one or two bytes depending on the declared maximum; the encoding is simple and explicit, which suits algorithm testing and intermediate exchange of scientific images.', traits: ['Raster', 'Uncompressed', 'Lossless'], layout: 'Starts with a two-byte magic: P2 for ASCII and P5 for binary; whitespace-separated width, height and maximum grey value follow, with hash comments allowed; pixels are decimal numbers for P2 or big-endian bytes for P5, one row per image line, and there is no extra header or checksum.' },
  },
  'pict': {
    zh: { summary: 'Apple QuickDraw 图元文件，用记录绘图指令的方式保存矢量图形与位图；Mac OS 时代的剪贴板与打印格式。', traits: ['矢量', '位图', '元数据'], layout: '没有固定魔数；由 Mac 保存的文件前 512 字节通常是保留的头，其中偏移 10 处给出图像边界；其后是图元序列，每个操作码前有 2 字节长度，版本由 0011 与 02FF 两个操作码标记，绘制指令带坐标与模式，最后以 00FF 的结束操作码收尾。' },
    en: { summary: 'Apple QuickDraw metafile that stores vector graphics and bitmaps as recorded drawing instructions; it was the clipboard and printing format of the classic Mac OS era and has been replaced by PDF and PNG.', traits: ['Vector', 'Raster', 'Metadata'], layout: 'There is no fixed magic; files saved by the Mac usually start with a 512-byte reserved header whose bytes at offset 10 give the picture bounds; a sequence of opcodes follows, each preceded by a 2-byte length, the version being marked by the opcodes 0011 and 02FF, drawing instructions carrying coordinates and modes, and an end opcode of 00FF closing the picture.' },
  },
  'plt': {
    zh: { summary: 'HPGL 绘图仪指令文件，纯文本用分号分隔的两位命令控制笔的起落、移动与线型；用于数控绘图与刻字设备。', traits: ['纯文本', '矢量', '可编辑'], layout: '纯文本，无二进制签名。命令以两个字母加参数、以分号结尾，例如用 PA 给出绝对坐标、PU 抬笔、PD 落笔，SP 选择笔号，IN 初始化设备；文件通常以 IN 与 SP 开头，坐标以绘图仪单位计，行分隔随意。' },
    en: { summary: 'HPGL plotter instruction file: plain text whose semicolon-terminated two-letter commands drive pen up and down, movement and line styles; it is used by CNC plotting and cutting devices and can be imported by drawing software.', traits: ['Plain text', 'Vector', 'Editable'], layout: 'Plain text with no binary signature. Commands are two letters plus arguments terminated by a semicolon: PA gives absolute coordinates, PU lifts the pen, PD lowers it, SP selects a pen and IN initialises the device; files usually start with IN and SP, coordinates are in plotter units, and line breaks are arbitrary.' },
  },
  'png': {
    zh: { summary: '无损压缩的位图格式，为网络与截图场景设计；支持 8 位与 16 位通道、alpha 透明与调色板。', traits: ['位图', '无损', '支持透明', '压缩'], layout: '前 8 字节固定为 89 50 4E 47 0D 0A 1A 0A；其后是若干 chunk，每个 chunk 为 4 字节大端长度、4 字节类型与数据再加 4 字节 CRC32，必需块是 IHDR、IDAT 与 IEND，数据经 DEFLATE 压缩。' },
    en: { summary: 'Lossless compressed raster format designed for the web and screenshots; it supports 8-bit and 16-bit channels, alpha transparency and palettes, but no animation, which the APNG extension adds instead.', traits: ['Raster', 'Lossless', 'Alpha', 'Compressed'], layout: 'The first eight bytes are always 89 50 4E 47 0D 0A 1A 0A; chunks follow, each a 4-byte big-endian data length, a 4-byte type and its data plus a 4-byte CRC32, with IHDR, IDAT and IEND mandatory, the data zlib DEFLATE-compressed, and ancillary chunks such as tEXt, gAMA and iCCP carrying metadata.' },
  },
  'pnm': {
    zh: { summary: 'Netpbm 的统称格式，涵盖 PBM 黑白、PGM 灰度与 PPM 彩色三类及其 ASCII 与二进制变体。', traits: ['位图', '未压缩', '无损'], layout: '文件以两字节魔数开头，P1 到 P3 为 ASCII 编码，P4 到 P6 为二进制编码，数字序号在家族内确定是黑白、灰度还是彩色；魔数之后以空白分隔给出宽高与最大灰度值，可插井号注释，随后是像素数据，无压缩也无校验和。' },
    en: { summary: 'Collective Netpbm format covering PBM black and white, PGM greyscale and PPM colour plus their ASCII and binary variants; a simple magic number distinguishes the exact type, which makes scripting easy.', traits: ['Raster', 'Uncompressed', 'Lossless'], layout: 'The file starts with a two-byte magic where P1 to P3 mean ASCII encoding and P4 to P6 binary, the digit identifying black and white, greyscale or colour; whitespace-separated width, height and maximum value follow with hash comments allowed, then pixel data, and there is no compression or checksum.' },
  },
  'postscript': {
    zh: { summary: 'Adobe 的页面描述语言，用栈式操作符描述文字与矢量图形的绘制，与设备分辨率无关；既用于打印，也是 PDF 的前身。', traits: ['纯文本', '矢量', '多页', '可编辑'], layout: '以 %!PS-Adobe- 加 DSC 版本开头，随后是 %%Title、%%BoundingBox 等约定注释；正文是逆波兰式操作符序列，字形与图像用 show、image 等操作绘制，每页以 showpage 结束，文件以 %%EOF 收尾；含位图时可出现二进制数据段。' },
    en: { summary: 'Page description language from Adobe whose stack-based operators describe text and vector graphics independently of device resolution; it served printing, preceded PDF and can hold several pages.', traits: ['Plain text', 'Vector', 'Multi-page', 'Editable'], layout: 'Begins with %!PS-Adobe- plus a DSC version, followed by conventional comments such as %%Title and %%BoundingBox; the body is a reverse-Polish sequence of operators, glyphs and images are painted by operators like show and image, each page ends with showpage, and the file closes with %%EOF; embedded bitmaps may introduce binary runs.' },
  },
  'ppm': {
    zh: { summary: 'Netpbm 家族的彩色位图，用三个样本表示 RGB 颜色，最大像素值可大于 255 以支持高动态范围；结构极简。', traits: ['位图', '未压缩', '无损'], layout: '以两字节魔数开头：ASCII 版为 P3，二进制版为 P6；随后空白分隔给出宽度、高度与最大样本值，若该值超过 255 则每个样本占 2 字节大端；像素按 RGB 顺序排列，P3 用十进制数字、P6 用字节表示，无压缩与校验。' },
    en: { summary: 'Colour bitmap from the Netpbm family whose pixels are three RGB samples, with a maximum value above 255 allowed for high dynamic range; the very simple layout makes it handy for exchange between imaging tools.', traits: ['Raster', 'Uncompressed', 'Lossless'], layout: 'Starts with a two-byte magic: P3 for ASCII and P6 for binary; whitespace-separated width, height and maximum sample value follow, and a value above 255 makes each sample two big-endian bytes; pixels are ordered RGB and written as decimal numbers for P3 or raw bytes for P6, with no compression or checksum.' },
  },
  'ppt': {
    zh: { summary: 'PowerPoint 97 至 2003 的二进制演示文档，用 OLE2 复合文件保存幻灯片、母版与嵌入对象。', traits: ['容器', '可编辑', '多页', '元数据'], layout: '以 OLE2 复合文件的 8 字节签名 D0 CF 11 E0 A1 B1 1A E1 开头，内部含 FAT 与目录项；幻灯片内容保存在名为 PowerPoint Document 的流中，以记录类型与长度组成的记录树组织。' },
    en: { summary: 'Binary presentation document from PowerPoint 97 through 2003, storing slides, masters and embedded objects in an OLE2 compound file; the layout is complex and undocumented, and current software still reads it.', traits: ['Container', 'Editable', 'Multi-page', 'Metadata'], layout: 'Begins with the 8-byte OLE2 compound file signature D0 CF 11 E0 A1 B1 1A E1 and holds a FAT with directory entries; slide content lives in a stream named PowerPoint Document, organised as a record tree of type and length fields, while other streams such as Current User and Pictures keep editing state and images.' },
  },
  'pptm': {
    zh: { summary: 'PowerPoint 2007 及以后启用宏的演示文稿，与 pptx 同为 OOXML 包，额外带 VBA 工程。', traits: ['压缩', '容器', '可编辑', '多页', '加密'], layout: 'ZIP 容器，以 50 4B 03 04 开头；[Content_Types].xml 声明部件类型，演示主体在 ppt/presentation.xml 与 ppt/slides/slideN.xml，宏代码位于 ppt/vbaProject.bin。' },
    en: { summary: 'Macro-enabled presentation from PowerPoint 2007 onward; it is an OOXML package like pptx but also carries a VBA project, so opening it may run macros and security policies usually block it by default.', traits: ['Compressed', 'Container', 'Editable', 'Multi-page', 'Encrypted'], layout: 'A ZIP container starting with 50 4B 03 04; [Content_Types].xml declares part types, the deck body sits in ppt/presentation.xml and ppt/slides/slideN.xml, masters and layouts live in ppt/slideMasters and slideLayouts, macro code is in ppt/vbaProject.bin, and .rels files describe relationships.' },
  },
  'pptx': {
    zh: { summary: 'Office Open XML 演示文稿，用 ZIP 打包 XML 部件描述幻灯片、版式、主题与媒体；格式开放。', traits: ['压缩', '容器', '可编辑', '多页', '元数据'], layout: 'ZIP 容器，以 50 4B 03 04 开头；[Content_Types].xml 列表部件，_rels/.rels 指向 ppt/presentation.xml，幻灯片为 ppt/slides/slideN.xml，媒体放在 ppt/media。' },
    en: { summary: 'Office Open XML presentation that packs XML parts for slides, layouts, themes and media into a ZIP; the format is open, supports collaborative comments, and the package can be encrypted as a whole.', traits: ['Compressed', 'Container', 'Editable', 'Multi-page', 'Metadata'], layout: 'A ZIP container starting with 50 4B 03 04; [Content_Types].xml lists the parts, _rels/.rels points at ppt/presentation.xml, slides are ppt/slides/slideN.xml, layouts and masters live in slideLayouts and slideMasters, themes in the theme directory, media under ppt/media, and comments and notes each have their own parts.' },
  },
  'psd': {
    zh: { summary: 'Adobe Photoshop 的原生文档，把图层、蒙版、通道、路径与调整层分层保存；能保留编辑状态。', traits: ['位图', '支持透明', '可编辑', '压缩', '元数据'], layout: '以 4 字节签名 38 42 50 53 开头，即字符 8BPS，随后是版本、保留区与通道数、高宽、位深和颜色模式；接着是颜色模式数据、图像资源块（以 8BIM 开头，含 ICC 与分辨率）、图层与蒙版信息段，最后是按通道平面排列的图像数据，可用 RLE 或 ZIP 压缩。' },
    en: { summary: 'Native Adobe Photoshop document that stores layers, masks, channels, paths and adjustment layers separately; it preserves the editing state and is often delivered as a flattened image with alpha.', traits: ['Raster', 'Alpha', 'Editable', 'Compressed', 'Metadata'], layout: 'Starts with the 4-byte signature 38 42 50 53, the characters 8BPS, then version, a reserved area, channel count, height and width, bit depth and colour mode; colour mode data, image resource blocks (starting with 8BIM, carrying ICC and resolution), and a layer and mask information section follow, with image data last in planar channel order, optionally RLE or ZIP compressed.' },
  },
  'qoi': {
    zh: { summary: 'Quite OK Image，为快速编解码设计的无损图像格式；算法只有游程、差分与索引几种操作，代码极短。', traits: ['位图', '无损', '压缩', '支持透明'], layout: '以 4 字节魔数 71 6F 69 66 开头，即字符 qoif，随后大端记录宽度、高度、通道数与色彩空间；之后是字节流式像素操作，首字节高两位决定操作类型（索引、差分、亮度差、游程、RGB 或 RGBA），文件末尾固定为 7 个零字节加 01。' },
    en: { summary: 'Quite OK Image, a lossless image format designed for fast encoding and decoding; its algorithm is just run-length, difference and index operations, the code is tiny, and it nears PNG ratios at several times the speed.', traits: ['Raster', 'Lossless', 'Compressed', 'Alpha'], layout: 'Starts with the 4-byte magic 71 6F 69 66, the characters qoif, then big-endian width, height, channel count and colour space; a byte-oriented stream of pixel operations follows whose first byte top two bits select index, difference, luma, run, RGB or RGBA, and the file always ends with seven zero bytes and 01.' },
  },
  'rar': {
    zh: { summary: 'RAR 压缩归档，私有算法在压缩率上长期领先 ZIP；支持固实压缩、分卷、恢复记录与 AES 加密。', traits: ['压缩', '无损', '容器', '加密'], layout: 'RAR 4 以 7 字节签名 52 61 72 21 1A 07 00 开头，RAR 5 以 52 61 72 21 1A 07 01 00 开头；随后是块序列，每块有类型、标志与长度（RAR 5 用可变长整数），含标记块、主档头、文件头与压缩数据块，末尾为结束块。' },
    en: { summary: 'RAR compressed archive whose proprietary algorithm long beat ZIP on ratio; it supports solid compression, volumes, recovery records and AES encryption, and the official writer is shareware.', traits: ['Compressed', 'Lossless', 'Container', 'Encrypted'], layout: 'RAR 4 opens with the 7-byte signature 52 61 72 21 1A 07 00 and RAR 5 with 52 61 72 21 1A 07 01 00; a block sequence follows where each block carries a type, flags and length (variable-length integers in RAR 5), covering marker, archive header, file headers and compressed data blocks, ending with an end block plus optional recovery records and encrypted headers.' },
  },
  'raw': {
    zh: { summary: '含义依赖上下文：多为相机传感器原始数据，未做去马赛克与白平衡，动态范围大但需专用解码；在图像工具中也指无头的裸像素转储。', traits: ['位图', '未压缩', '元数据'], layout: '没有统一签名。相机原始文件多基于 TIFF 或自有容器（如 CR2 以 TIFF 头开头）并带厂商私有的 IFD 元数据；图像工具中的裸像素转储则完全没有头，宽高、通道数与位深必须由外部参数指定，字节序决定解释方式。' },
    en: { summary: 'Meaning depends on context: most often camera sensor data before demosaicing and white balance, with wide dynamic range but needing dedicated decoding; in imaging tools it also means a headerless dump of raw pixels.', traits: ['Raster', 'Uncompressed', 'Metadata'], layout: 'There is no common signature. Camera raw files are usually built on TIFF or a vendor container, for example CR2 starting with a TIFF header and carrying private IFD metadata, whereas a raw pixel dump has no header at all: width, channel count and bit depth must come from external parameters, and endianness decides interpretation.' },
  },
  'rmvb': {
    zh: { summary: 'RealMedia 的可变码率影片，用 RealVideo 与 RealAudio 有损编码；按场景复杂度动态分配码率。', traits: ['容器', '有损', '压缩', '流式'], layout: '以 4 字节签名 2E 52 4D 46 开头，即 .RMF；随后是对象序列，每个对象有 4 字节标识与长度，包括文件头对象、属性对象 PROP、各媒体属性对象 MDPR、数据对象 DATA 与索引对象 INDX，码流为 RealVideo 帧与 RealAudio 帧的交错。' },
    en: { summary: 'Variable-bitrate RealMedia movie using lossy RealVideo and RealAudio codecs; the bitrate flexes with scene complexity, and it was a leading format for low-bandwidth web video.', traits: ['Container', 'Lossy', 'Compressed', 'Streamable'], layout: 'Begins with the 4-byte signature 2E 52 4D 46, the characters .RMF; objects follow, each with a 4-byte identifier and length, including the file header object, the properties object PROP, per-stream media properties MDPR, the data object DATA and the index object INDX, with RealVideo and RealAudio frames interleaved.' },
  },
  'rst': {
    zh: { summary: 'reStructuredText 纯文本标记，用下划线标题与双冒号块表达结构，是 Python 文档的官方格式。', traits: ['纯文本', '可编辑', '未压缩'], layout: '纯文本，无二进制签名。标题下方用等号、连字符等符号划出与标题等长的下划线；指令以两个点加空格开头（如 toctree 与 code-block），字段列表写成 名称: 值，行内角色用冒号包裹如 :math:，注释同样以两个点开始。' },
    en: { summary: 'Plain-text reStructuredText markup whose underlined headings and double-colon literal blocks express structure; docutils or Sphinx renders it, and it is the official authoring format for Python documentation.', traits: ['Plain text', 'Editable', 'Uncompressed'], layout: 'Plain text with no binary signature. A heading is underlined by a row of characters such as equals signs or hyphens matching its length; directives start with two dots and a space (toctree, code-block and so on), field lists are written as name: value, inline roles are wrapped in colons such as :math:, and comments also begin with two dots.' },
  },
  'rtf': {
    zh: { summary: '微软富文本格式，用可读的 ASCII 控制词描述字体、段落与表格，并能以十六进制内嵌图片；纯文本外壳使其兼容性极强。', traits: ['纯文本', '可编辑', '多页', '元数据'], layout: '以左花括号加反斜杠 rtf 加版本号开头，例如 {\\rtf1\\ansi；内容由花括号分组，控制词以反斜杠引导并以空格或标点分隔，非 ASCII 字符用反斜杠加单引号与两位十六进制表示，Unicode 用 u 控制词，图片以十六进制文本放在 pict 组中。' },
    en: { summary: 'Microsoft Rich Text Format, whose readable ASCII control words describe fonts, paragraphs and tables and can embed pictures as hexadecimal text; the plain-text shell gives it outstanding compatibility and it is still widely read and written.', traits: ['Plain text', 'Editable', 'Multi-page', 'Metadata'], layout: 'Starts with an opening brace, a backslash and the word rtf plus a version, for example {\\rtf1\\ansi; braces group the content, control words start with a backslash and end at a space or punctuation, non-ASCII characters use a backslash, an apostrophe and two hex digits, Unicode uses the u control word, and pictures sit as hexadecimal text inside a pict group.' },
  },
  'sgi': {
    zh: { summary: 'Silicon Graphics 的 IRIS 图像格式，按通道平面存储，支持 8 位与 16 位、灰度与 RGBA。', traits: ['位图', '无损', '压缩', '支持透明'], layout: '头部为 512 字节大端结构：2 字节魔数 01 DA 表示游程压缩、01 01 表示逐行未压缩，随后是存储方式、每通道字节数、维度、宽高与通道数、最小最大值以及 80 字节图像名与颜色表；若用压缩，头部之后是行起始表与行长度表，再是按平面排列的像素。' },
    en: { summary: 'IRIS image format from Silicon Graphics, stored in channel planes with 8-bit and 16-bit depths, greyscale and RGBA; it appears mostly in early 3D software and render output and supports optional run-length compression.', traits: ['Raster', 'Lossless', 'Compressed', 'Alpha'], layout: 'The header is a 512-byte big-endian structure: the 2-byte magic 01 DA means run-length and 01 01 verbatim rows, followed by storage format, bytes per channel, dimension, width, height and channel count, minimum and maximum values, an 80-byte image name and a colour map; with compression, row start and row size tables precede the planar pixel data.' },
  },
  'sun': {
    zh: { summary: 'Sun 工作站的光栅文件格式，用于 SunOS；支持 1 到 32 位灰度与真彩，可选游程压缩。', traits: ['位图', '无损', '压缩'], layout: '以 4 字节大端魔数 59 A6 6A 95 开头，随后 28 字节头给出宽高、每像素位数、数据长度、类型（1 为逐行、2 为游程编码）、色彩表类型与色彩表长度；其后依次是色彩表、可选的行偏移表与像素数据，若用游程则在每行前写入转义字节与重复计数。' },
    en: { summary: 'Raster file format from Sun Microsystems for SunOS workstations; it covers 1-bit to 32-bit depths in greyscale, pseudo-colour and true colour with optional run-length compression, all in a simple big-endian layout.', traits: ['Raster', 'Lossless', 'Compressed'], layout: 'Starts with the 4-byte big-endian magic 59 A6 6A 95, then a 28-byte header giving width and height, bits per pixel, data length, type (1 for plain rows, 2 for run-length), colour map type and colour map length; the colour map, optional row offset table and pixel data follow, and run-length rows prefix escapes and repeat counts.' },
  },
  'svg': {
    zh: { summary: '基于 XML 的二维矢量图形格式，用元素描述路径、形状、文字与滤镜；可缩放到任意尺寸、支持透明与内嵌位图。', traits: ['矢量', '纯文本', '可编辑', '支持透明'], layout: '纯文本，无二进制签名。通常以 XML 声明开头，根元素 svg 带 xmlns 与 viewBox 属性，图形元素如 path、rect、circle 通过 d 或坐标属性定义几何，样式可由属性、style 或内联 CSS 给出，位图以 data URI 内嵌。' },
    en: { summary: 'XML-based two-dimensional vector graphics format whose elements describe paths, shapes, text and filters; it scales to any size, supports transparency and embedded bitmaps, and dominates web icons and diagrams.', traits: ['Vector', 'Plain text', 'Editable', 'Alpha'], layout: 'Plain text with no binary signature. It usually opens with an XML declaration and an svg root carrying xmlns and viewBox attributes; drawing elements such as path, rect and circle define geometry through d or coordinate attributes, styling comes from attributes, style or inline CSS, and bitmaps are embedded as data URIs.' },
  },
  'svgz': {
    zh: { summary: 'gzip 压缩的 SVG，内容与 SVG 完全相同，只是整体被压缩以减小网页传输体积。', traits: ['矢量', '压缩', '支持透明'], layout: '外层就是标准 gzip 流：以 1F 8B 08 开头，可选原始文件名与时间戳，之后是 DEFLATE 数据与 CRC32；解压后得到的是普通 SVG 文本，同样以 XML 声明与 svg 根元素开始，因此读图工具需先解压再解析。' },
    en: { summary: 'Gzip-compressed SVG with exactly the same content, only the whole file is compressed to cut transfer size; browsers must recognise it from a Content-Encoding header or the .svgz extension and decompress it first.', traits: ['Vector', 'Compressed', 'Alpha'], layout: 'The outer layer is a standard gzip stream starting with 1F 8B 08, an optional original file name and timestamp, then DEFLATE data and a CRC32; what decompresses out is ordinary SVG text that also begins with an XML declaration and an svg root, so readers must inflate before parsing.' },
  },
  'sxc': {
    zh: { summary: 'OpenOffice.org 1.x 的电子表格格式，用 ZIP 包加 XML 描述工作表与公式。', traits: ['压缩', '容器', '可编辑', '元数据'], layout: 'ZIP 容器，首个条目 mimetype 以存储方式未压缩保存，内容为 application/vnd.sun.xml.calc；随后是 META-INF/manifest.xml、content.xml（工作表与单元格）、styles.xml。' },
    en: { summary: 'Spreadsheet format of OpenOffice.org 1.x that packs XML describing sheets and formulas into a ZIP, predating ODF; modern office suites still read it so documents can be migrated.', traits: ['Compressed', 'Container', 'Editable', 'Metadata'], layout: 'A ZIP container whose first entry, mimetype, is stored uncompressed and holds application/vnd.sun.xml.calc; META-INF/manifest.xml, content.xml (sheets and cells), styles.xml, meta.xml and settings.xml follow, using the same compression as ODF but older XML namespaces.' },
  },
  'sxi': {
    zh: { summary: 'OpenOffice.org 1.x 的演示文稿格式，ZIP 包内含 XML 描述的幻灯片与母版。', traits: ['压缩', '容器', '可编辑', '多页', '元数据'], layout: 'ZIP 容器，mimetype 首条目未压缩并写明 application/vnd.sun.xml.impress；内部结构与 ODF 演示文稿类似，有 manifest.xml 列部件，content.xml 保存幻灯片页面与绘图对象。' },
    en: { summary: 'Presentation format of OpenOffice.org 1.x whose ZIP package holds XML-described slides and masters; it belongs to the generation before ODF and has largely given way to odp, though archives still contain it.', traits: ['Compressed', 'Container', 'Editable', 'Multi-page', 'Metadata'], layout: 'A ZIP container whose first mimetype entry is uncompressed and names application/vnd.sun.xml.impress; the inner structure resembles ODF presentations, with manifest.xml listing parts, content.xml holding slide pages and drawing objects, styles.xml and meta.xml holding styles and metadata, and images in the Pictures directory.' },
  },
  'sxw': {
    zh: { summary: 'OpenOffice.org 1.x 的文本文档格式，ZIP 包加 XML 保存段落、样式与表格；已由 odt 取代。', traits: ['压缩', '容器', '可编辑', '多页', '元数据'], layout: 'ZIP 容器，首个条目 mimetype 未压缩，内容为 application/vnd.sun.xml.writer；其余部件包括 META-INF/manifest.xml、content.xml（正文段落与表格）、styles.xml（命名样式与页面设置）。' },
    en: { summary: 'Text document format of OpenOffice.org 1.x that stores paragraphs, styles and tables as XML in a ZIP; odt replaced it, but historic documents and bulk conversions still meet it.', traits: ['Compressed', 'Container', 'Editable', 'Multi-page', 'Metadata'], layout: 'A ZIP container whose first mimetype entry is uncompressed and holds application/vnd.sun.xml.writer; the remaining parts include META-INF/manifest.xml, content.xml (body paragraphs and tables), styles.xml (named styles and page setup), meta.xml (author and timestamps) and settings.xml, with images under Pictures.' },
  },
  'tar': {
    zh: { summary: 'Unix 磁带归档格式，只把多个文件与目录顺序拼接而不压缩；保留权限、属主与时间戳，常与 gzip 或 xz 组合使用。', traits: ['容器', '未压缩', '无损', '元数据'], layout: '由 512 字节定长块组成；每个文件前有 512 字节头，依次是 100 字节文件名、权限、属主、大小、修改时间、8 字节校验和、类型标志、链接名，偏移 257 处为 ustar 魔数与版本；文件数据按 512 字节对齐补齐，归档以两个全零块结束。' },
    en: { summary: 'Unix tape archive that simply concatenates files and directories without compressing them; it preserves permissions, owners and timestamps and is usually paired with gzip or xz, making it a staple of software distribution.', traits: ['Container', 'Uncompressed', 'Lossless', 'Metadata'], layout: 'Built from fixed 512-byte blocks: each file is preceded by a 512-byte header holding a 100-byte name, mode, owner, size, modification time, an 8-byte checksum, a type flag and link name, with the ustar magic and version at offset 257; file data is padded to 512-byte boundaries and the archive ends with two all-zero blocks.' },
  },
  'tex': {
    zh: { summary: 'TeX 与 LaTeX 的排版源文件，纯文本用反斜杠命令控制断行、公式与字体；由引擎编译为 DVI 或 PDF。', traits: ['纯文本', '可编辑', '多页'], layout: '纯文本，无二进制签名。命令以反斜杠引导，可带花括号参数与方括号可选参数，分组用花括号界定作用域，注释以百分号开始直到行尾；普通 TeX 文件常以 bye 结束，LaTeX 文件则以 end 加 document 命令收尾，编码一般为 UTF-8。' },
    en: { summary: 'Typesetting source for TeX and LaTeX: plain text in which backslash commands control line breaking, formulas and fonts; an engine compiles it to DVI or PDF, and a large package ecosystem supports long structured documents.', traits: ['Plain text', 'Editable', 'Multi-page'], layout: 'Plain text with no binary signature. Commands start with a backslash and may take braced arguments and bracketed options, braces delimit grouping scope, and a percent sign starts a comment running to the end of the line; plain TeX often ends with bye while LaTeX closes with an end document command, normally in UTF-8.' },
  },
  'text': {
    zh: { summary: '无格式纯文本，只保存字符与换行，不含样式、字体或结构信息；编码与换行习惯需由 BOM 或外部约定判断。', traits: ['纯文本', '可编辑', '未压缩'], layout: '纯文本，无二进制签名，也没有元数据字段。内容是一串字符，行以 LF、CRLF 或 CR 分隔，编码可能是 UTF-8（可带 BOM）、UTF-16 或某地区编码；制表符与空格用于对齐，除换行外不含任何控制结构。' },
    en: { summary: 'Unformatted plain text that stores only characters and line breaks, with no styling, fonts or structure; the encoding and line-ending convention must come from a BOM or outside agreement, which makes it the most portable exchange form.', traits: ['Plain text', 'Editable', 'Uncompressed'], layout: 'Plain text with no binary signature and no metadata fields. The content is a run of characters whose lines end in LF, CRLF or CR, the encoding may be UTF-8 (optionally with a BOM), UTF-16 or a regional code page, and tabs and spaces provide alignment; apart from line breaks there is no control structure at all.' },
  },
  'textile': {
    zh: { summary: 'Textile 轻量标记语言，用简洁符号表达标题、强调、列表、表格与链接，常被内容管理系统使用并渲染为 HTML。', traits: ['纯文本', '可编辑', '未压缩'], layout: '纯文本，无二进制签名。行首 h1 加点号表示标题，星号与下划线包裹表示粗体斜体，井号与星号开头构成有序无序列表，竖线画表格，引号加冒号写链接；段落之间以空行分隔，通常保存为 UTF-8 与 LF 换行。' },
    en: { summary: 'Textile lightweight markup whose terse symbols express headings, emphasis, lists, tables and links; content management systems often render it to HTML, and its syntax stays close to natural writing.', traits: ['Plain text', 'Editable', 'Uncompressed'], layout: 'Plain text with no binary signature. A leading h1 with a dot marks a heading, asterisks and underscores wrap bold and italic, hashes and asterisks open ordered or unordered lists, pipes draw tables and a quoted phrase with a colon forms a link; paragraphs are separated by blank lines and files are normally UTF-8 with LF endings.' },
  },
  'tga': {
    zh: { summary: 'Truevision 的 Targa 位图，结构简单支持 8 到 32 位与 alpha 通道，可选游程压缩。', traits: ['位图', '支持透明', '压缩', '元数据'], layout: '以 18 字节定长头开头，字段依次是图像标识长度、色彩表类型、图像类型码（1 到 3 为未压缩、9 到 11 为游程压缩）、色彩表规格、原点坐标、宽高、像素深度与图像描述字节（低四位给 alpha 位数，第 5 位表示自顶向下）。' },
    en: { summary: 'Truevision Targa bitmap with a simple layout supporting 8 to 32-bit depths and an alpha channel plus optional run-length compression; it is common for game textures and compositing, and since the header has no signature the footer identifies the file.', traits: ['Raster', 'Alpha', 'Compressed', 'Metadata'], layout: 'Opens with a fixed 18-byte header holding the image id length, colour map type, image type code (1 to 3 uncompressed, 9 to 11 run-length), colour map specification, origin coordinates, width and height, pixel depth and an image descriptor byte whose low four bits give alpha bits and whose bit 5 means top-down rows; the last 26 bytes of the file carry the TRUEVISION-XFILE signature and extension area pointers.' },
  },
  'tgz': {
    zh: { summary: '先 tar 打包再用 gzip 压缩的组合产物，是 Unix 世界分发源码与备份的常见形式；扩展名也写作 tar.gz。', traits: ['压缩', '无损', '容器'], layout: '外层是 gzip 流，以 1F 8B 08 开头，尾部带 CRC32 与原始长度；解压后得到标准 tar 归档，由 512 字节块组成，每个文件前有含 ustar 魔数的头块，数据按 512 字节对齐，并以两个全零块结束。' },
    en: { summary: 'A tar archive that was then gzip-compressed, a common way to distribute source code and backups in the Unix world; the extension is also written tar.gz and extraction means gunzip first, then tar.', traits: ['Compressed', 'Lossless', 'Container'], layout: 'The outer layer is a gzip stream starting with 1F 8B 08 and ending with a CRC32 and the original length; what emerges is a standard tar archive of 512-byte blocks, each file preceded by a header block carrying the ustar magic, data padded to 512-byte boundaries, and two all-zero blocks closing the archive.' },
  },
  'tif': {
    zh: { summary: '标签化图像文件格式，用标签自由描述位深、压缩与色彩空间，是印刷、扫描与归档领域的通用位图；支持多页。', traits: ['位图', '无损', '多页', '压缩', '元数据'], layout: '以 4 字节头开头：小端为 49 49 2A 00、大端为 4D 4D 00 2A，随后 4 字节指向第一个图像文件目录；每个目录先有 2 字节条目计数，再是若干 12 字节条目（标签、类型、计数、值或偏移），末尾指向下一目录。' },
    en: { summary: 'Tagged Image File Format, which describes bit depth, compression and colour space through tags; it is the general-purpose raster format for print, scanning and archiving and supports multiple pages, lossless compression and high dynamic range.', traits: ['Raster', 'Lossless', 'Multi-page', 'Compressed', 'Metadata'], layout: 'Opens with a 4-byte header, 49 49 2A 00 for little-endian or 4D 4D 00 2A for big-endian, then a 4-byte offset to the first image file directory; each directory holds a 2-byte entry count followed by 12-byte entries (tag, type, count, value or offset) and a 4-byte pointer to the next directory; pixels are stored in strips or tiles with no, LZW, Deflate or JPEG compression.' },
  },
  'ts': {
    zh: { summary: 'MPEG 传输流，为不可靠信道设计，把音视频切成定长小包并在包头记录节目信息；数字电视广播与蓝光光盘使用。', traits: ['容器', '有损', '压缩', '流式'], layout: '由 188 字节定长包构成，每包以同步字节 47 开头，随后是传输错误标志、负载起始标志、13 位包标识与加扰控制，再接自适应字段与负载；节目关联表与节目映射表用固定包标识描述各流的内容与类型，时间同步靠节目参考时钟。' },
    en: { summary: 'MPEG transport stream, designed for unreliable channels: audio and video are cut into fixed-size packets whose headers carry programme information, which suits digital television broadcast, Blu-ray discs and live captures.', traits: ['Container', 'Lossy', 'Compressed', 'Streamable'], layout: 'Built from fixed 188-byte packets, each starting with the sync byte 47 followed by a transport error flag, payload unit start flag, a 13-bit packet identifier and scrambling control, then an adaptation field and payload; the programme association and programme map tables use reserved packet identifiers to describe stream contents and types, and timing relies on the programme clock reference.' },
  },
  'tsv': {
    zh: { summary: '制表符分隔值的纯文本表格，与 CSV 类似但用制表符分列；因为制表符在数据中极少出现，解析比 CSV 简单。', traits: ['纯文本', '可编辑', '未压缩'], layout: '纯文本，无二进制签名。每行一条记录，字段以制表符分隔，行以 LF 或 CRLF 结束；因为缺少统一的转义约定，字段中一般不允许出现制表符与换行，首行是否为表头取决于约定，编码通常为 UTF-8。' },
    en: { summary: 'Plain-text tabular data with tab-separated values, like CSV but splitting columns on tabs; since tabs rarely occur inside data, parsing is simpler than CSV and suits program-to-program exchange.', traits: ['Plain text', 'Editable', 'Uncompressed'], layout: 'Plain text with no binary signature. Each line is a record whose fields are separated by tab characters and whose terminator is LF or CRLF; because there is no agreed escaping, fields normally contain no tabs or line breaks, whether the first row is a header is conventional, and the encoding is usually UTF-8.' },
  },
  'typ': {
    zh: { summary: 'Typst 排版系统的源文件，纯文本用等号标题与井号函数调用描述文档，编译速度快、错误提示友好。', traits: ['纯文本', '可编辑', '多页'], layout: '纯文本，无二进制签名。文件按标记模式书写：等号开头分级标题，星号与下划线表示强调，美元符号包裹行内公式；井号进入代码模式调用函数或读取变量，花括号包裹代码块，双斜杠开始注释，编码为 UTF-8。' },
    en: { summary: 'Source file for the Typst typesetting system: plain text whose equals-sign headings and hash-prefixed function calls describe a document, with fast compilation and helpful errors as a modern alternative to LaTeX.', traits: ['Plain text', 'Editable', 'Multi-page'], layout: 'Plain text with no binary signature. The file is written in markup mode: leading equals signs give heading levels, asterisks and underscores mark emphasis, dollar signs wrap inline formulas; a hash switches to code mode for function calls or variables, braces wrap code blocks, double slashes start comments, and the encoding is UTF-8.' },
  },
  'typst': {
    zh: { summary: 'Typst 文档的规范扩展名，内容与 typ 相同；由 typst 编译器输出 PDF 或 PNG 等结果。', traits: ['纯文本', '可编辑', '多页'], layout: '纯文本，无二进制签名。结构与 typ 一致：标记模式中行首等号表示标题、连字符或加号表示列表，内容块用方括号给出，井号引导函数与变量，数学公式写在美元符号之间，导入与包含语句使用 import 与 include 关键字。' },
    en: { summary: 'Canonical extension for Typst documents with the same content as typ; the typst compiler emits PDF, PNG and other outputs, supports template imports and incremental compilation.', traits: ['Plain text', 'Editable', 'Multi-page'], layout: 'Plain text with no binary signature. The structure matches typ: in markup mode leading equals signs mark headings and hyphens or plus signs mark lists, content blocks use square brackets, a hash introduces functions and variables, math sits between dollar signs, and imports and includes use the import and include keywords.' },
  },
  'viff': {
    zh: { summary: 'Khoros 可视化工具的图像格式，为图像处理流水线设计；头部用文本字段描述尺寸、数据类型与波段。', traits: ['位图', '无损', '压缩', '元数据'], layout: '文件以定长的 1024 字节头开始，头内以文本字段记录行数、列数、波段数、数据类型（字节、短整、浮点、复数等）、色彩空间与压缩方式，字段名与值以冒号等形式分隔；头后按波段或分段存放数据，压缩可选游程或自适应的分段方式。' },
    en: { summary: 'Image format of the Khoros visualisation toolkit, designed for image-processing pipelines; a text-field header describes size, data type and bands, and pixels may be integer, floating point or complex to suit scientific computation.', traits: ['Raster', 'Lossless', 'Compressed', 'Metadata'], layout: 'The file starts with a fixed 1024-byte header whose text fields record rows, columns, band count, data type (byte, short, float, complex and so on), colour space and compression method, with names and values separated by colons or similar; data follows by band or by segment, optionally run-length or adaptively compressed.' },
  },
  'vob': {
    zh: { summary: 'DVD 视频对象文件，实质是 MPEG-2 节目流并混入导航包；视频为 MPEG-2、音频多为 AC-3 或 DTS。', traits: ['容器', '有损', '压缩', '加密'], layout: '数据以节目流包结构组织，每组以 3 字节起始码 00 00 01 加 1 字节流标识开头，包头为 BA 并带时间戳；每约半秒插入一个导航包，用私有流 1 与子流标识 BF 携带 PCI 与 DSI 两种高亮与搜索信息，其余为 MPEG-2 视频与 AC-3 音频的 PES 包。' },
    en: { summary: 'DVD video object file, in effect an MPEG-2 programme stream mixed with navigation packets; video is MPEG-2 and audio is usually AC-3 or DTS, all lossy, and the payload may be scrambled with CSS content protection.', traits: ['Container', 'Lossy', 'Compressed', 'Encrypted'], layout: 'Data is organised as programme stream packs, each beginning with the 3-byte start code 00 00 01 plus a 1-byte stream id and a BA pack header carrying timestamps; roughly every half second a navigation pack appears, using private stream 1 with substream id BF to carry the PCI and DSI highlight and search structures, while the rest holds PES packets of MPEG-2 video and AC-3 audio.' },
  },
  'wav': {
    zh: { summary: '微软与 IBM 定义的波形音频文件，基于 RIFF，通常存放未压缩线性 PCM；是音频编辑的通用格式。', traits: ['未压缩', '无损', '容器'], layout: '以 4 字节 RIFF 加小端长度与类型 WAVE 开头，之后是若干块，每块为 4 字节标识与 4 字节长度：fmt 块给出编码格式、声道数、采样率、字节率与位深，fact 与 bext 等块存附加信息，data 块保存按声道交错的样本，块长为奇数时补一个填充字节。' },
    en: { summary: 'Waveform audio file defined by Microsoft and IBM on RIFF, normally holding uncompressed linear PCM; the simple, unencumbered layout makes it the de facto standard for audio editing, speech and test signals.', traits: ['Uncompressed', 'Lossless', 'Container'], layout: 'Starts with the four bytes RIFF, a little-endian length and the type WAVE, then chunks of a 4-byte identifier and 4-byte length: the fmt chunk gives the encoding format, channel count, sample rate, byte rate and bit depth, fact and bext chunks hold extra information, and the data chunk stores interleaved samples, with a pad byte when a chunk length is odd.' },
  },
  'wbmp': {
    zh: { summary: '无线应用协议定义的单色位图，为早期手机浏览器显示小图片而设计；每像素一位、无灰度、无压缩，体积小但表现力极有限。', traits: ['位图', '未压缩', '无损'], layout: '头部依次是 1 字节类型（固定为 0）、1 字节固定头（固定为 0），随后是多字节整数形式的宽度与高度，每个字节只用低 7 位，最高位为 1 表示还有后续字节，数值按大端组合；像素数据紧随其后，每行按位自左至右打包，行末不足一字节补零。' },
    en: { summary: 'Monochrome bitmap defined by the Wireless Application Protocol for showing small images in early mobile browsers; one bit per pixel, no grey levels and no compression, so files are small but extremely limited.', traits: ['Raster', 'Uncompressed', 'Lossless'], layout: 'The header is a 1-byte type (always 0), a 1-byte fixed header (always 0) and then width and height as multi-byte integers where each byte uses only its low seven bits, a high bit of 1 meaning more bytes follow and the value assembled big-endian; pixel data follows immediately, packed bit by bit per row with the row tail padded by zero bits.' },
  },
  'webm': {
    zh: { summary: '面向网页的开放容器，是 Matroska 的受限子集；视频用 VP8、VP9 或 AV1。', traits: ['容器', '有损', '压缩', '流式'], layout: '以 EBML 头开始，魔数为 1A 45 DF A3，DocType 字段为 webm，DocTypeVersion 通常为 2 或 4；其后是 Segment 元素，内含 Info（时基与时长）、Tracks、Clusters（按时间码组织的块数据）。' },
    en: { summary: 'Open container for the web, a restricted subset of Matroska; video uses VP8, VP9 or AV1 and audio uses Vorbis or Opus, all lossy except lossless AV1, and browsers support it natively.', traits: ['Container', 'Lossy', 'Compressed', 'Streamable'], layout: 'Starts with an EBML header whose magic is 1A 45 DF A3 and whose DocType field reads webm with a DocTypeVersion of usually 2 or 4; a Segment element follows with Info (timecode scale and duration), Tracks and Clusters holding timecode-organised blocks, and WebM restricts the permitted codecs and elements to keep browser compatibility.' },
  },
  'webp': {
    zh: { summary: '谷歌推出的网络图像格式，同体积下画质优于 JPEG；有损模式基于 VP8 帧内编码，无损模式用预测加熵编码。', traits: ['位图', '有损', '无损', '支持透明', '支持动画'], layout: '基于 RIFF：以 4 字节 RIFF 加小端长度与类型 WEBP 开头，其后是块序列，第一块决定变体：VP8 为有损、VP8L 为无损、VP8X 为扩展容器（可再含 ALPH 透明、ANIM 与 ANMF 动画帧、ICCP 色彩配置、EXIF 与 XMP 元数据）。' },
    en: { summary: 'Web image format from Google that beats JPEG quality at the same size; the lossy mode builds on VP8 intra coding and the lossless mode uses prediction plus entropy coding, with alpha and animation supported.', traits: ['Raster', 'Lossy', 'Lossless', 'Alpha', 'Animation'], layout: 'RIFF-based: it opens with the four bytes RIFF, a little-endian length and the type WEBP, then a chunk sequence whose first chunk sets the variant: VP8 for lossy, VP8L for lossless, VP8X for the extended container that may also carry ALPH transparency, ANIM and ANMF animation frames, ICCP colour profiles and EXIF or XMP metadata.' },
  },
  'wma': {
    zh: { summary: 'Windows Media Audio，微软的有损音频编码，同码率下优于早期 MP3。', traits: ['有损', '压缩', '容器', '元数据'], layout: '文件外层是 ASF，以 16 字节头对象 GUID 30 26 B2 75 8E 66 CF 11 A6 D9 00 AA 00 62 CE 6C 开头，随后是对象大小与数量；头对象内的流属性对象记录编解码标识与格式参数，音频数据放在数据对象中按包排列。' },
    en: { summary: 'Windows Media Audio, Microsoft lossy audio codec that beat early MP3 at equal bitrate; Lossless and Pro variants also exist, and all of them are wrapped in the ASF container.', traits: ['Lossy', 'Compressed', 'Container', 'Metadata'], layout: 'The outer layer is ASF, starting with the 16-byte header object GUID 30 26 B2 75 8E 66 CF 11 A6 D9 00 AA 00 62 CE 6C followed by the object size and count; a stream properties object inside the header records the codec identifier and format parameters, audio data sits in the data object as packets, and optional index and content description objects hold title and author information.' },
  },
  'wmf': {
    zh: { summary: '微软 Windows 图元文件，用记录序列保存 GDI 绘图调用，属矢量格式但精度与功能有限。', traits: ['矢量', '位图', '元数据'], layout: '若为可放置格式，则以 4 字节键值 D7 CD C6 9A 加 22 字节头开头；否则是 18 字节头，以 01 00 加头长度 09 00 与版本 00 03 开头；其后每条记录是 4 字节长度、2 字节功能码与参数，以功能码 0 的结束记录收尾。' },
    en: { summary: 'Microsoft Windows Metafile, recording GDI drawing calls as a sequence of records; it is vector in nature but limited in precision and features, and often appears as clipboard or legacy Office artwork.', traits: ['Vector', 'Raster', 'Metadata'], layout: 'A placeable file starts with the 4-byte key D7 CD C6 9A (read as 9A C6 CD D7) plus a 22-byte header giving the bounding box and units; otherwise an 18-byte header opens with 01 00, a header length of 09 00 and version 00 03 and carries the file size and object count; each later record is a 4-byte length, a 2-byte function code and parameters, and a function zero record ends the file.' },
  },
  'wmv': {
    zh: { summary: 'Windows Media Video，微软的有损视频编码，采用 ASF 容器封装；支持流式传输与可变码率。', traits: ['容器', '有损', '压缩', '流式'], layout: '外层为 ASF，以 16 字节头对象 GUID 30 26 B2 75 8E 66 CF 11 A6 D9 00 AA 00 62 CE 6C 开头，随后是 8 字节对象大小与对象数量；头对象内用流属性对象声明 WMV 编解码标识与分辨率、帧率等参数。' },
    en: { summary: 'Windows Media Video, the lossy video codec from Microsoft, wrapped in the ASF container; it supports streaming, variable bitrate and digital rights management and was common in early online video.', traits: ['Container', 'Lossy', 'Compressed', 'Streamable'], layout: 'The outer layer is ASF, starting with the 16-byte header object GUID 30 26 B2 75 8E 66 CF 11 A6 D9 00 AA 00 62 CE 6C followed by an 8-byte object size and object count; a stream properties object in the header declares the WMV codec identifier along with resolution and frame rate, image data sits in packets inside the data object, and timestamps are carried within the packets.' },
  },
  'wpd': {
    zh: { summary: 'WordPerfect 文本文档，历史悠久的字处理格式；二进制保存文字、格式化码与图形，结构未公开且随版本演进。', traits: ['可编辑', '容器', '元数据'], layout: '较新的版本以 4 字节签名 FF 57 50 43 开头，即 0xFF 加字符 WPC；其后是产品与版本标识以及若干文档区，格式信息以类似前缀码的标记嵌在文本流中而非独立标记语言，文件尾可带图形与修订信息，整体结构未公开。' },
    en: { summary: 'WordPerfect text document, a long-lived word-processing format; it stores text, formatting codes and graphics in binary, the layout is undocumented and evolves with each release, and complete reading needs a dedicated filter.', traits: ['Editable', 'Container', 'Metadata'], layout: 'Newer releases start with the 4-byte signature FF 57 50 43, that is 0xFF followed by the characters WPC; a product and version identifier comes next along with several document areas, and formatting uses prefix-code style markers embedded in the text stream rather than a separate markup language, with graphics and revision data near the end; the overall layout is undocumented.' },
  },
  'wpg': {
    zh: { summary: 'WordPerfect Graphics 矢量图元文件，用于在 WordPerfect 文档中嵌入插图。', traits: ['矢量', '位图', '元数据'], layout: '以 4 字节签名 FF 57 50 47 开头，即 0xFF 加字符 WPG；随后是 16 字节头，给出格式版本与对象表的位置和长度，其后按记录组织绘图数据，每条记录以 1 字节类型与 4 字节长度开头，类型区分线段、多边形、位图等对象。' },
    en: { summary: 'WordPerfect Graphics metafile for embedding illustrations in WordPerfect documents; it records drawing objects as a sequence of records and can include bitmaps and fill patterns, and is rarely seen now.', traits: ['Vector', 'Raster', 'Metadata'], layout: 'Starts with the 4-byte signature FF 57 50 47, that is 0xFF followed by the characters WPG; a 16-byte header then gives the format version and the location and length of the object table, after which drawing data is organised as records, each beginning with a 1-byte type and a 4-byte length where the type distinguishes line, polygon and bitmap objects.' },
  },
  'wps': {
    zh: { summary: 'WPS Office 文字文档，金山办公的格式；现代版本内部与 docx 相同的 OOXML 结构。', traits: ['压缩', '容器', '可编辑', '元数据'], layout: '主流的新版本是 ZIP 包，以 50 4B 03 04 开头，内含 [Content_Types].xml 与 word/document.xml 等部件，与 docx 基本一致，因此多数工具可直接当 docx 读取；旧版本的二进制格式没有统一定义，需要专门过滤器判断。' },
    en: { summary: 'Word-processing document of WPS Office from Kingsoft; current releases use the same OOXML structure as docx, while older ones may be proprietary binary or legacy Microsoft formats, so compatibility depends on the version.', traits: ['Compressed', 'Container', 'Editable', 'Metadata'], layout: 'The mainstream current version is a ZIP package starting with 50 4B 03 04 and containing parts such as [Content_Types].xml and word/document.xml, essentially identical to docx so most tools read it directly; the older binary format has no single definition and requires a dedicated filter to identify.' },
  },
  'xbm': {
    zh: { summary: 'X BitMap，以 C 语言源码形式表示一位黑白位图；文本可编译进程序或供 X 窗口系统读取。', traits: ['纯文本', '位图', '可编辑'], layout: '纯文本，无二进制签名。文件由预处理宏与数组声明组成：先用 define 给出宽度与高度，例如 名称_width 与 名称_height，随后是 static unsigned char 名称_bits 数组，元素为十六进制字节，每字节自低位到高位对应一行中从左到右的八个像素。' },
    en: { summary: 'X BitMap represents a one-bit black and white image as C source code; the text can be compiled into programs or read by the X Window System, and it is easy for scripts to generate and for version control to track.', traits: ['Plain text', 'Raster', 'Editable'], layout: 'Plain text with no binary signature. The file consists of preprocessor macros and an array declaration: define statements give the width and height as name_width and name_height, then a static unsigned char name_bits array holds hexadecimal bytes, each byte mapping the eight pixels of a row from left to right with the least significant bit first.' },
  },
  'xls': {
    zh: { summary: 'Excel 97 至 2003 的二进制工作簿，用 OLE2 复合文件保存工作表、公式与图表。', traits: ['容器', '可编辑', '元数据'], layout: '以 OLE2 复合文件签名 D0 CF 11 E0 A1 B1 1A E1 开头，内部有一个名为 Workbook 的流；该流由 BIFF 记录序列构成，每条记录为 2 字节类型与 2 字节长度加数据，用 BOF 与 EOF 划分工作表，共享字符串集中在 SST 记录。' },
    en: { summary: 'Binary workbook from Excel 97 through 2003, storing sheets, formulas and charts in an OLE2 compound file; a sheet holds about 65536 rows at most and current Excel still reads and writes the format.', traits: ['Container', 'Editable', 'Metadata'], layout: 'Begins with the OLE2 compound file signature D0 CF 11 E0 A1 B1 1A E1 and contains a stream named Workbook; that stream is a sequence of BIFF records, each a 2-byte type and 2-byte length plus data, with BOF and EOF records delimiting sheets, shared strings collected in the SST record and number formats defined in FORMAT and XF records.' },
  },
  'xlsm': {
    zh: { summary: 'Excel 2007 及以后启用宏的工作簿，与 xlsx 同为 OOXML 包但内含 VBA 工程；打开时可能执行宏。', traits: ['压缩', '容器', '可编辑', '加密'], layout: 'ZIP 容器，以 50 4B 03 04 开头；[Content_Types].xml 声明部件类型，工作簿结构在 xl/workbook.xml 与 xl/worksheets/sheetN.xml，共享字符串在 xl/sharedStrings.xml。' },
    en: { summary: 'Macro-enabled workbook from Excel 2007 onward; it is an OOXML package like xlsx but also contains a VBA project, so opening it may run macros and corporate environments usually block it with a warning.', traits: ['Compressed', 'Container', 'Editable', 'Encrypted'], layout: 'A ZIP container starting with 50 4B 03 04; [Content_Types].xml declares part types, the workbook structure lives in xl/workbook.xml and xl/worksheets/sheetN.xml, shared strings sit in xl/sharedStrings.xml, macro code is in xl/vbaProject.bin, and the whole package can be encrypted with ECMA-376 Agile Encryption.' },
  },
  'xlsx': {
    zh: { summary: 'Office Open XML 工作簿，用 ZIP 打包 XML 描述工作表、公式与样式；单表可达百万行以上，格式开放。', traits: ['压缩', '容器', '可编辑', '元数据'], layout: 'ZIP 容器，以 50 4B 03 04 开头；[Content_Types].xml 列出部件，_rels/.rels 指向 xl/workbook.xml，其中声明各工作表及其关系标识，工作表内容为 xl/worksheets/sheetN.xml。' },
    en: { summary: 'Office Open XML workbook that packs XML describing sheets, formulas and styles into a ZIP; a sheet can exceed a million rows and the open, compact format now carries most spreadsheet data.', traits: ['Compressed', 'Container', 'Editable', 'Metadata'], layout: 'A ZIP container starting with 50 4B 03 04; [Content_Types].xml lists the parts, _rels/.rels points at xl/workbook.xml which declares each sheet with its relationship identifier, sheet content lives in xl/worksheets/sheetN.xml, strings are pooled in xl/sharedStrings.xml, and styles, themes and images are separate parts.' },
  },
  'xml': {
    zh: { summary: '可扩展标记语言，用自描述的元素与属性表达层级数据；纯文本、语言中立、模式可校验，广泛用于配置文件与数据交换。', traits: ['纯文本', '可编辑', '未压缩'], layout: '纯文本，无二进制签名，规范要求以 UTF-8 为默认编码且可带 BOM。文件通常以 XML 声明开头声明版本与编码，随后是唯一根元素，元素由开始标签、内容与结束标签组成，属性写成 名称="值"，特殊字符用实体引用，注释与 CDATA 段有专门语法。' },
    en: { summary: 'Extensible Markup Language, expressing hierarchical data through self-describing elements and attributes; it is plain text, language-neutral and schema-validatable, which makes it a general base for configurations, data exchange and document markup.', traits: ['Plain text', 'Editable', 'Uncompressed'], layout: 'Plain text with no binary signature, defaulting to UTF-8 per the specification and optionally carrying a BOM. A file usually opens with an XML declaration giving version and encoding, followed by a single root element; elements consist of start tag, content and end tag, attributes are written as name="value", special characters use entity references, and comments and CDATA sections have dedicated syntax.' },
  },
  'xpm': {
    zh: { summary: 'X PixMap，以 C 语言源码表示彩色图标位图，支持多色与透明色；用字符索引调色板。', traits: ['纯文本', '位图', '可编辑', '支持透明'], layout: '纯文本，无二进制签名。文件由注释标记 XPM 与 static char 名称数组构成：第一行字符串给出宽、高、颜色数与每像素字符数，随后每行定义一个颜色项，字符加 c 加颜色值，颜色 None 表示透明，最后每行一个字符串表示一排像素的字符索引。' },
    en: { summary: 'X PixMap represents colour icon bitmaps as C source code with support for many colours and a transparent colour; characters index the palette, so it can be compiled straight into X programs or desktop themes.', traits: ['Plain text', 'Raster', 'Editable', 'Alpha'], layout: 'Plain text with no binary signature. The file pairs an XPM comment marker with a static char array: the first string gives width, height, colour count and characters per pixel, each following string defines one colour entry as a character, a c and a colour value, the colour None meaning transparent, and the remaining strings give one row of pixel characters each.' },
  },
  'xwd': {
    zh: { summary: 'X Window Dump，X 窗口系统抓取窗口或屏幕得到的图像；头部把像素格式、字节序与位掩码全部写清。', traits: ['位图', '未压缩', '元数据'], layout: '前 4 字节为大端整数，给出头部的总字节数（不少于 100 字节，含窗口名），随后是大端的版本号、像素图格式与深度、宽高与偏移、字节序与位序、每像素位数、每行字节数、视觉类型、红绿蓝掩码、色彩表条目数与色彩表规模等字段，头之后是色彩表和像素数据。' },
    en: { summary: 'X Window Dump, an image captured from a window or screen by the X Window System; the header states the pixel format, byte order and bit masks explicitly, so any machine can parse it correctly.', traits: ['Raster', 'Uncompressed', 'Metadata'], layout: 'The first 4 bytes are a big-endian integer giving the total header size in bytes (at least 100 and including the window name), followed by big-endian fields for version, pixmap format and depth, width, height and offsets, byte order and bit order, bits per pixel, bytes per line, visual class, red, green and blue masks, colour map entry count and colour map size; colour map entries and pixel data come after the header.' },
  },
  'xz': {
    zh: { summary: '基于 LZMA2 的压缩格式，压缩率通常优于 gzip 与 bzip2；支持多块与多线程解码、完整性校验。', traits: ['压缩', '无损', '流式'], layout: '文件以 6 字节魔数 FD 37 7A 58 5A 00 开头，随后是流标志字节与 4 字节 CRC32；之后是若干数据块，每块有块头（块大小、标志与可选的压缩后与原始大小，以及 LZMA2 等过滤器标识），块数据填充到 4 字节对齐，再是索引记录。' },
    en: { summary: 'Compression format built on LZMA2 whose ratio usually beats gzip and bzip2; it supports multiple blocks, multithreaded decoding and integrity checks, and is widely used for source tarballs and container images.', traits: ['Compressed', 'Lossless', 'Streamable'], layout: 'The file starts with the 6-byte magic FD 37 7A 58 5A 00, then a stream flags byte and a 4-byte CRC32; data blocks follow, each with a block header (block size, flags, optional compressed and uncompressed sizes and filter identifiers such as LZMA2), block data padded to a multiple of four, then an index record, and the final 12-byte stream footer carries a CRC32 and a backward size.' },
  },
  'zip': {
    zh: { summary: '应用最广的压缩归档格式，支持多文件、目录结构与多种压缩算法；无损、可加密、可随机读取单个条目，几乎被所有系统原生支持。', traits: ['压缩', '无损', '容器', '加密'], layout: '每个条目以本地文件头 50 4B 03 04 开头，含版本、标志、压缩方法（0 存储、8 DEFLATE、14 LZMA）、时间戳、CRC32 与大小及文件名；数据之后可选数据描述符，全部条目之后是中央目录与结尾记录 50 4B 05 06。' },
    en: { summary: 'The most widely used compressed archive format, holding multiple files with directory structure and several compression methods; it is lossless, encryptable, able to read single entries at random, and natively supported almost everywhere.', traits: ['Compressed', 'Lossless', 'Container', 'Encrypted'], layout: 'Each entry opens with the local file header 50 4B 03 04 carrying version, flags, compression method (0 stored, 8 DEFLATE, 12 bzip2, 14 LZMA, 93 zstd), timestamps, CRC32 and sizes plus the file name; data follows with an optional data descriptor; after all entries come the central directory (50 4B 01 02) and the end record (50 4B 05 06), with ZIP64 extension records when limits are exceeded.' },
  },
};

/** 取某个格式的说明；没有收录就返回 null */
export function formatInfoOf(format, locale) {
  const hit = INFO[String(format || '').toLowerCase()];
  if (!hit) return null;
  return hit[locale === 'en-US' ? 'en' : 'zh'] || hit.zh;
}

/** 收录了多少个格式（自检用） */
export function formatInfoCount() {
  return Object.keys(INFO).length;
}

/** 全部收录的格式名（自检用） */
export function formatInfoKeys() {
  return Object.keys(INFO);
}

export default { formatInfoOf, formatInfoCount, formatInfoKeys };
